  <footer role="contentinfo">
    <div class="container">
  <div data-lang-content data-lang="es">© 2025 · Informe ODS 2 · Versión para uso académico.</div>
  <div data-lang-content data-lang="en">© 2025 · SDG 2 Report · Academic use version.</div>
    </div>
  </footer>

  <script>
    // Intro overlay: muestra UDES y ODS/SDG 1 y revela el contenido con animación
    (function() {
      const overlay = document.getElementById('intro-overlay');
      const siteBg = document.getElementById('site-bg');
      if (!overlay) return;
      const prefersReduced = window.matchMedia('(prefers-reduced-motion: reduce)').matches;
      function done() {
        document.body.classList.remove('intro-playing');
        document.body.classList.add('intro-done');
        if (overlay && overlay.parentNode) overlay.parentNode.removeChild(overlay);
        enableParallax();
      }
      if (prefersReduced) { done(); return; }
      document.body.classList.add('intro-playing');
      // Oculta el overlay después de una breve pausa para permitir leer el título
      setTimeout(() => {
        overlay.classList.add('hide');
        overlay.addEventListener('animationend', done, { once: true });
      }, 1200);

      function enableParallax() {
        if (!siteBg) return;
        if (prefersReduced) return;
        let mouseX = 0, mouseY = 0;
        let scrollY = 0;
        let ticking = false;
        const maxMouse = 14;  // px
        const maxScroll = 10; // px

        function onMove(e) {
          const x = (e.clientX / window.innerWidth) - 0.5;
          const y = (e.clientY / window.innerHeight) - 0.5;
          mouseX = x * maxMouse;
          mouseY = y * maxMouse;
          requestTick();
        }
        function onScroll() {
          // Desplazamiento vertical sutil según scroll
          const p = Math.min(1, window.scrollY / (window.innerHeight * 2));
          scrollY = (p * 2 - 1) * maxScroll; // de -maxScroll a +maxScroll
          requestTick();
        }
        function requestTick() {
          if (!ticking) {
            ticking = true;
            requestAnimationFrame(update);
          }
        }
        function update() {
          ticking = false;
          siteBg.style.transform = `translate3d(${mouseX.toFixed(1)}px, ${(mouseY/2 + scrollY).toFixed(1)}px, 0)`;
        }
        window.addEventListener('mousemove', onMove, { passive: true });
        window.addEventListener('scroll', onScroll, { passive: true });
        onScroll();
      }
    })();

    // Activa automáticamente el ODS actual en la barra según el archivo
    (function() {
      const m = (location.pathname || '').match(/ods(\d+)_informe\.html$/);
      const current = m ? m[1] : null;
      if (!current) return;
      document.querySelectorAll('.sdg-nav-item').forEach(a => {
        a.classList.toggle('active', a.getAttribute('data-sdg') === current);
      });
    })();

    // Conmutación de idioma ES/EN con persistencia
    (function() {
      const LANG_KEY = 'ods-lang';
      const btnEs = document.querySelector('[data-lang-btn="es"]');
      const btnEn = document.querySelector('[data-lang-btn="en"]');
      const langEls = document.querySelectorAll('[data-lang-content]');

      function applyLang(lang) {
        document.documentElement.setAttribute('lang', lang);
        langEls.forEach(el => {
          const isVisible = el.getAttribute('data-lang') === lang;
          el.setAttribute('data-visible', isVisible ? 'true' : 'false');
        });
        btnEs.classList.toggle('active', lang === 'es');
        btnEn.classList.toggle('active', lang === 'en');
        btnEs.setAttribute('aria-pressed', lang === 'es');
        btnEn.setAttribute('aria-pressed', lang === 'en');
        localStorage.setItem(LANG_KEY, lang);
      }

      const initial = localStorage.getItem(LANG_KEY) || 'es';
      applyLang(initial);
      btnEs.addEventListener('click', () => applyLang('es'));
      btnEn.addEventListener('click', () => applyLang('en'));
    })();

    // Contadores dinámicos al entrar en viewport
    (function() {
      const counters = document.querySelectorAll('[data-counter]');
      if (!('IntersectionObserver' in window)) {
        counters.forEach(el => el.textContent = Number(el.dataset.target).toLocaleString());
        return;
      }
      const obs = new IntersectionObserver(entries => {
        entries.forEach(entry => {
          if (entry.isIntersecting) {
            const el = entry.target;
            const target = Number(el.dataset.target);
            const duration = 1200; // ms
            const start = performance.now();
            const startVal = 0;
            function tick(now) {
              const p = Math.min(1, (now - start) / duration);
              const eased = 1 - Math.pow(1 - p, 3);
              const val = Math.round(startVal + (target - startVal) * eased);
              el.textContent = val.toLocaleString();
              if (p < 1) requestAnimationFrame(tick);
            }
            requestAnimationFrame(tick);
            obs.unobserve(el);
          }
        });
      }, { threshold: 0.4 });
      counters.forEach(el => obs.observe(el));
    })();

    // Carrusel simple de aliados
    (function() {
      const track = document.querySelector('[data-carousel-track]');
      if (!track) return;
      const slides = Array.from(track.children);
      const btnPrev = document.querySelector('[data-prev]');
      const btnNext = document.querySelector('[data-next]');
      const dotsWrap = document.querySelector('[data-dots]');

      const visiblePerView = () => {
        const w = window.innerWidth;
        if (w < 640) return 2;
        if (w < 960) return 3;
        return 4;
      };

      let index = 0;
      let perView = visiblePerView();
      let pages = Math.max(1, Math.ceil(slides.length / perView));

      function buildDots() {
        dotsWrap.innerHTML = '';
        for (let i = 0; i < pages; i++) {
          const d = document.createElement('div');
          d.className = 'dot' + (i === 0 ? ' active' : '');
          d.addEventListener('click', () => goTo(i));
          dotsWrap.appendChild(d);
        }
      }

      function update() {
        perView = visiblePerView();
        pages = Math.max(1, Math.ceil(slides.length / perView));
        const slideWidthPct = 100 / perView;
        slides.forEach(s => s.style.flex = `0 0 ${slideWidthPct}%`);
        index = Math.min(index, pages - 1);
        track.style.transform = `translateX(-${index * 100}%)`;
        [...dotsWrap.children].forEach((d, i) => d.classList.toggle('active', i === index));
      }

      function goTo(i) { index = (i + pages) % pages; update(); }
      function prev() { goTo(index - 1); }
      function next() { goTo(index + 1); }

      btnPrev.addEventListener('click', prev);
      btnNext.addEventListener('click', next);
      window.addEventListener('resize', () => { const old = pages; update(); if (pages !== old) buildDots(); });

      buildDots();
      update();

      let timer = setInterval(next, 4000);
      track.closest('.carousel-viewport').addEventListener('mouseenter', () => clearInterval(timer));
      track.closest('.carousel-viewport').addEventListener('mouseleave', () => timer = setInterval(next, 4000));
    })();
  </script>
</body>
