    or public.ods_report_archive.raw_html is distinct from excluded.raw_html;

insert into public.ods_report_archive (ods, edition, source, parsed, raw_html)
values (3, 2025, 'sdgudes.github.io', $ods_json${"ods":3,"edicion":2025,"fuente":"sdgudes.github.io","archivo":"ods3_informe.html","titulo":{"es":"ODS 3: Salud y Bienestar","en":"SDG 3: Good Health and Well-Being"},"tesis":[{"es":"La Salud y Bienestar (ODS 3) representa el compromiso de la Universidad de Santander (UDES) con garantizar vidas saludables y promover el bienestar para todos en todas las edades. La UDES aborda este objetivo mediante la formación de profesionales de la salud de alta calidad, la investigación aplicada en salud pública, y la extensión social que impacta directamente en las comunidades. Desde la respuesta a crisis sanitarias hasta la promoción de estilos de vida saludables en el campus, la UDES materializa su compromiso con el bienestar integral de la sociedad.","en":"Good Health and Well-Being (SDG 3) represents the Universidad de Santander (UDES) commitment to ensuring healthy lives and promoting well-being for all at all ages. The UDES addresses this objective through training high-quality health professionals, applied public health research, and social outreach that directly impacts communities. From responding to health crises to promoting healthy lifestyles on campus, the UDES materializes its commitment to the comprehensive well-being of society."}],"cifras":[{"v":"4,849","etiqueta":{"es":"Graduados Totales","en":"Total Graduates"},"nota":{"es":"En el período evaluado, la UDES entregó al país y al mundo 4,849 profesionales listos para transformar la sociedad. ¡Una muestra de nuestra productividad académica y el impacto de nuestros egresados en diversos campos!","en":"During the evaluated period, UDES delivered 4,849 professionals ready to transform society to the country and the world. A testament to our academic productivity and the impact of our graduates across diverse fields!"}},{"v":"835","etiqueta":{"es":"Profesionales de la Salud","en":"Health Professionals"},"nota":{"es":"De ese gran total, 835 nuevos profesionales se graduaron de nuestras áreas de la salud. Esto refleja el compromiso de la UDES para fortalecer el sistema de salud y atender las necesidades más apremiantes de nuestras comunidades.","en":"From that grand total, 835 new professionals graduated from our health programs. This reflects UDES's commitment to strengthening the health system and addressing the most pressing needs of our communities."}},{"v":"17.22%","etiqueta":{"es":"Concentración Estratégica","en":"Strategic Concentration"},"nota":{"es":"¡El 17.22% de nuestros graduados son profesionales de la salud! Esta alta proporción (≈0.1722) subraya la vocación de servicio y la alta inversión de la UDES en programas de calidad que forman a los líderes del sector salud. Estamos sembrando bienestar.","en":"17.22% of our graduates are health professionals! This high proportion (≈0.1722) underscores UDES's service vocation and strong investment in quality programs that train leaders in the health sector. We are sowing well-being."}}],"cifras_no_importadas":[],"videos":[],"enlaces":[],"imagenes":[{"src":"https://sdgbook.com/wp-content/uploads/sites/2/2019/09/3.png","alt":{"es":"Logo oficial del Objetivo de Desarrollo Sostenible 3: Salud y Bienestar","en":"Logo oficial del Objetivo de Desarrollo Sostenible 3: Salud y Bienestar"},"pie":{"es":"","en":""},"tipo":"ilustracion-ods","zona":"portada"}],"fotos_udes":[],"graficos":[],"secciones":[{"titulo":{"es":"","en":""},"piezas":[{"t":"parrafo","zona":"portada","texto":{"es":"La Salud y Bienestar (ODS 3) representa el compromiso de la Universidad de Santander (UDES) con garantizar vidas saludables y promover el bienestar para todos en todas las edades. La UDES aborda este objetivo mediante la formación de profesionales de la salud de alta calidad, la investigación aplicada en salud pública, y la extensión social que impacta directamente en las comunidades. Desde la respuesta a crisis sanitarias hasta la promoción de estilos de vida saludables en el campus, la UDES materializa su compromiso con el bienestar integral de la sociedad.","en":"Good Health and Well-Being (SDG 3) represents the Universidad de Santander (UDES) commitment to ensuring healthy lives and promoting well-being for all at all ages. The UDES addresses this objective through training high-quality health professionals, applied public health research, and social outreach that directly impacts communities. From responding to health crises to promoting healthy lifestyles on campus, the UDES materializes its commitment to the comprehensive well-being of society."}},{"t":"imagen","zona":"portada","src":"https://sdgbook.com/wp-content/uploads/sites/2/2019/09/3.png","alt":{"es":"Logo oficial del Objetivo de Desarrollo Sostenible 3: Salud y Bienestar","en":"Logo oficial del Objetivo de Desarrollo Sostenible 3: Salud y Bienestar"},"pie":{"es":"","en":""},"tipo":"ilustracion-ods"}]},{"titulo":{"es":"Resumen Ejecutivo","en":"Executive Summary"},"piezas":[{"t":"parrafo","zona":"cuerpo","texto":{"es":"La Universidad de Santander (UDES) demuestra un compromiso central con el Objetivo de Desarrollo Sostenible (ODS) 1, Fin de la Pobreza, articulando sus funciones sustantivas para impulsar la transformación social en sus áreas de influencia. Este compromiso se materializa en estrategias que buscan la inclusión de comunidades vulnerables y el desarrollo económico regional. La UDES utiliza la educación y la extensión como herramientas clave, por ejemplo, mediante la Escuela Empresarial Udeista, que ofrece el Diplomado de Economía Popular para fortalecer unidades productivas. Asimismo, el proyecto \"Maquilando Felicidad\" busca el empoderamiento económico de jóvenes y mujeres de Piedecuesta a través de programas de formación integral.","en":"The Universidad de Santander (UDES) demonstrates a core commitment to Sustainable Development Goal (SDG) 1, No Poverty, aligning its substantive functions to drive social transformation in its areas of influence. This commitment materializes through strategies aimed at including vulnerable communities and promoting regional economic development. Education and outreach serve as key tools—for example, the Udeista Business School’s Popular Economy Diploma strengthens productive units. Likewise, the \"Maquilando Felicidad\" project fosters the economic empowerment of young people and women in Piedecuesta through comprehensive training programs."}},{"t":"parrafo","zona":"cuerpo","texto":{"es":"La estrategia de UDES para el ODS 1 abarca la dignificación a través de la inclusión social, la equidad y el bienestar comunitario. El Modelo Interprofesional (MIUDES), por ejemplo, apoya directamente a poblaciones vulnerables, incluyendo acciones cruciales de salud, prevención (como la promoción de la lactancia materna para la seguridad alimentaria y nutricional), y estructurando planes de apoyo para fortalecer los componentes alimentario e higiénico en las familias. Además, la UDES ha desarrollado su Política de Inclusión, Equidad y Diversidad, y forma líderes a través de alianzas con la Universidad para la Paz (UPEACE), incluyendo módulos sobre la lucha contra la pobreza, reconociendo que la equidad y la no discriminación son fundamentales para el desarrollo sustentable y la paz.","en":"UDES’s SDG 1 strategy encompasses dignity through social inclusion, equity, and community well-being. The Interprofessional Model (MIUDES) directly supports vulnerable populations with crucial health and prevention actions (such as promoting breastfeeding for food and nutrition security) and by structuring support plans to strengthen food and hygiene components in families. Additionally, UDES has developed its Policy of Inclusion, Equity, and Diversity and trains leaders through alliances with the University for Peace (UPEACE), including modules on the fight against poverty, recognizing that equity and non-discrimination are fundamental to sustainable development and peace."}}]},{"titulo":{"es":"UDES: Impulsando la Salud en la Región","en":"UDES: Driving Health in the Region"},"piezas":[{"t":"parrafo","zona":"cuerpo","texto":{"es":"¡Un Logro de Impacto Global! La Universidad de Santander (UDES) se destaca en el prestigioso THE Impact Rankings, reafirmando nuestro compromiso con la salud y el bienestar.","en":"A Global Impact Achievement! The University of Santander (UDES) stands out in the prestigious THE Impact Rankings, reaffirming our commitment to health and well-being."}},{"t":"cifra","zona":"cuerpo","v":"4,849","etiqueta":{"es":"Graduados Totales","en":"Total Graduates"},"nota":{"es":"En el período evaluado, la UDES entregó al país y al mundo 4,849 profesionales listos para transformar la sociedad. ¡Una muestra de nuestra productividad académica y el impacto de nuestros egresados en diversos campos!","en":"During the evaluated period, UDES delivered 4,849 professionals ready to transform society to the country and the world. A testament to our academic productivity and the impact of our graduates across diverse fields!"},"contador":false,"numerica":true},{"t":"cifra","zona":"cuerpo","v":"835","etiqueta":{"es":"Profesionales de la Salud","en":"Health Professionals"},"nota":{"es":"De ese gran total, 835 nuevos profesionales se graduaron de nuestras áreas de la salud. Esto refleja el compromiso de la UDES para fortalecer el sistema de salud y atender las necesidades más apremiantes de nuestras comunidades.","en":"From that grand total, 835 new professionals graduated from our health programs. This reflects UDES's commitment to strengthening the health system and addressing the most pressing needs of our communities."},"contador":false,"numerica":true},{"t":"cifra","zona":"cuerpo","v":"17.22%","etiqueta":{"es":"Concentración Estratégica","en":"Strategic Concentration"},"nota":{"es":"¡El 17.22% de nuestros graduados son profesionales de la salud! Esta alta proporción (≈0.1722) subraya la vocación de servicio y la alta inversión de la UDES en programas de calidad que forman a los líderes del sector salud. Estamos sembrando bienestar.","en":"17.22% of our graduates are health professionals! This high proportion (≈0.1722) underscores UDES's service vocation and strong investment in quality programs that train leaders in the health sector. We are sowing well-being."},"contador":false,"numerica":true}]},{"titulo":{"es":"Proyectos de Extensión y Servicio Comunitario","en":"Outreach Projects and Community Service"},"piezas":[{"t":"parrafo","zona":"cuerpo","texto":{"es":"La UDES utiliza su extensión social para impactar directamente a comunidades en situación de vulnerabilidad, abordando múltiples dimensiones de la pobreza:","en":"UDES uses its social outreach to directly impact communities in vulnerable situations, addressing multiple dimensions of poverty:"}},{"t":"titulo","zona":"cuerpo","nivel":3,"texto":{"es":"Modelo Interprofesional de la UDES (MIUDES)","en":"UDES Interprofessional Model (MIUDES)"}},{"t":"item","zona":"cuerpo","texto":{"es":"Realiza acciones a nivel familiar, individual y comunitario en barrios como Los Colorados, en la comuna 1 del norte de Bucaramanga.","en":"Conducts actions at family, individual, and community levels in neighborhoods such as Los Colorados, in commune 1 of northern Bucaramanga."}},{"t":"item","zona":"cuerpo","texto":{"es":"Basado en la metodología Investigación Acción Participativa, ofrece acompañamiento interprofesional a poblaciones vulnerables.","en":"Based on Participatory Action Research methodology, offers interprofessional support to vulnerable populations."}},{"t":"item","zona":"cuerpo","texto":{"es":"Demostró un impacto crucial durante la emergencia sanitaria por COVID-19 (2020-2021), diseñando estrategias que incluyeron consulta médica, primeros auxilios psicológicos, pedagogía de prevención y un plan padrino para fortalecer el componente alimentario e higiénico.","en":"Demonstrated crucial impact during the COVID-19 health emergency (2020-2021), designing strategies including medical consultation, psychological first aid, prevention pedagogy, and a sponsor plan to strengthen food and hygiene components."}},{"t":"item","zona":"cuerpo","texto":{"es":"Sus mesas de trabajo abordan salud, saneamiento y ambiente, gobernanza, habilidades, y tecnología y comunicaciones.","en":"Working groups address health, sanitation and environment, governance, skills, and technology and communications."}},{"t":"item","zona":"cuerpo","texto":{"es":"Los estudiantes realizan proyectos de construcción de paz y tejido social en la comunidad.","en":"Students carry out peace-building and social fabric projects in the community."}},{"t":"titulo","zona":"cuerpo","nivel":3,"texto":{"es":"Proyecto \"Maquilando Felicidad\" (Piedecuesta)","en":"\"Maquilando Felicidad\" Project (Piedecuesta)"}},{"t":"item","zona":"cuerpo","texto":{"es":"Liderado por la UDES en colaboración con la Fundación Marie Poussepin en comunidades vulnerables de Piedecuesta (sector Barro Blanco).","en":"Led by UDES in collaboration with the Marie Poussepin Foundation in vulnerable communities of Piedecuesta (Barro Blanco sector)."}},{"t":"item","zona":"cuerpo","texto":{"es":"Enfoque directo en la mitigación de la pobreza mediante el empoderamiento económico, capacitando a 25 jóvenes y mujeres en panadería y chocolatería para generar ingresos y emprender negocios.","en":"Direct focus on poverty mitigation through economic empowerment, training 25 young people and women in bakery and chocolate-making to generate income and start businesses."}},{"t":"item","zona":"cuerpo","texto":{"es":"Incluye servicios de Salud Integral (atención a población infantil, madres gestantes, adultos mayores) y talleres de bienestar emocional y prevención de violencias de género.","en":"Includes Comprehensive Health services (care for children, pregnant mothers, elderly) and workshops on emotional well-being and prevention of gender-based violence."}},{"t":"item","zona":"cuerpo","texto":{"es":"Involucra programas de Ingenierías, Ciencias Médicas y de la Salud, Ciencias Administrativas y Sociales.","en":"Involves programs from Engineering, Medical and Health Sciences, Administrative and Social Sciences."}},{"t":"titulo","zona":"cuerpo","nivel":3,"texto":{"es":"Apoyo a Población en Situación de Vulnerabilidad Social","en":"Support for Socially Vulnerable Populations"}},{"t":"item","zona":"cuerpo","texto":{"es":"Estudiantes de la UDES contribuyen a mejorar la calidad de vida de habitantes de calle y sus familias en Bucaramanga a través de la Fundación Posada del Peregrino, proporcionando alimento, vestido y educación para los niños.","en":"UDES students contribute to improving the quality of life of homeless people and their families in Bucaramanga through the Posada del Peregrino Foundation, providing food, clothing, and education for children."}},{"t":"item","zona":"cuerpo","texto":{"es":"El proyecto \"El Recolector\" en Hogares Crea (rehabilitación por consumo de sustancias) fomenta la seguridad alimentaria y el emprendimiento mediante huertas caseras, funcionando también como terapia ocupacional.","en":"\"El Recolector\" project at Hogares Crea (substance abuse rehabilitation) promotes food security and entrepreneurship through home gardens, also functioning as occupational therapy."}}]},{"titulo":{"es":"Desarrollo Económico y Formación para la Prosperidad","en":"Economic Development and Training for Prosperity"},"piezas":[{"t":"parrafo","zona":"cuerpo","texto":{"es":"La UDES promueve el crecimiento económico inclusivo y el emprendimiento como herramientas clave para salir de la pobreza:","en":"UDES promotes inclusive economic growth and entrepreneurship as key tools to overcome poverty:"}},{"t":"titulo","zona":"cuerpo","nivel":3,"texto":{"es":"Diplomado de Economía Popular","en":"Popular Economy Diploma Program"}},{"t":"item","zona":"cuerpo","texto":{"es":"La Escuela Empresarial Udeista ofrece un diplomado en economía popular para fortalecer unidades productivas.","en":"The Udeista Business School offers a diploma in popular economy to strengthen productive units."}},{"t":"item","zona":"cuerpo","texto":{"es":"Beneficia a participantes que han firmado el acuerdo de paz o se han acogido a la Ley de Justicia y Paz, incluyendo personas de Santander y el Magdalena Medio.","en":"Benefits participants who have signed the peace agreement or have availed themselves of the Justice and Peace Law, including people from Santander and the Magdalena Medio."}},{"t":"titulo","zona":"cuerpo","nivel":3,"texto":{"es":"Impulso Empresarial y Mipyme","en":"Business Promotion and SMEs"}},{"t":"item","zona":"cuerpo","texto":{"es":"Organización de ferias internacionales de emprendimiento (\"Yo Emprendo\") para fortalecer habilidades y potenciar el alcance de iniciativas.","en":"Organization of international entrepreneurship fairs (\"Yo Emprendo\") to strengthen skills and enhance the reach of initiatives."}},{"t":"item","zona":"cuerpo","texto":{"es":"Alianzas para fortalecer el sector empresarial y las Mipyme, como el convenio con la Cámara de Comercio de Bucaramanga para capacitar tenderos.","en":"Alliances to strengthen the business sector and SMEs, such as the agreement with the Bucaramanga Chamber of Commerce to train shopkeepers."}},{"t":"item","zona":"cuerpo","texto":{"es":"VI Congreso Internacional de la Facultad de Ciencias Económicas, enfocado en innovación empresarial para potenciar las Mipyme de la región.","en":"VI International Congress of the Faculty of Economic Sciences, focused on business innovation to boost regional SMEs."}},{"t":"item","zona":"cuerpo","texto":{"es":"Apoyo a artesanos y emprendedores mediante eventos como la Feria Homenaje al Artesano, que buscan el desarrollo sostenible económico y social en la región.","en":"Support for artisans and entrepreneurs through events such as the Artisan Tribute Fair, seeking sustainable economic and social development in the region."}},{"t":"titulo","zona":"cuerpo","nivel":3,"texto":{"es":"Articulación con Gobiernos Locales","en":"Local Government Coordination"}},{"t":"item","zona":"cuerpo","texto":{"es":"La UDES es miembro del Consejo Territorial de Planeación (CTP) en Bucaramanga, aportando propuestas, metas e indicadores para el Plan de Desarrollo.","en":"UDES is a member of the Territorial Planning Council (CTP) in Bucaramanga, contributing proposals, goals, and indicators for the Development Plan."}},{"t":"item","zona":"cuerpo","texto":{"es":"Alianzas estratégicas con la Gobernación de Santander y las Alcaldías de Bucaramanga, Piedecuesta y Girón para alinear proyectos en el Plan de Desarrollo Municipal y Departamental.","en":"Strategic alliances with the Government of Santander and the municipalities of Bucaramanga, Piedecuesta, and Girón to align projects in the Municipal and Departmental Development Plan."}},{"t":"item","zona":"cuerpo","texto":{"es":"Proyectos estratégicos que impulsan el desarrollo económico, como el fortalecimiento de clústeres productivos y la masificación de la educación.","en":"Strategic projects that promote economic development, such as strengthening productive clusters and expanding education."}}]},{"titulo":{"es":"Inclusión y No Discriminación","en":"Inclusion and Non-Discrimination"},"piezas":[{"t":"parrafo","zona":"cuerpo","texto":{"es":"La UDES trabaja activamente para eliminar las barreras de exclusión que perpetúan la pobreza y la desigualdad:","en":"UDES actively works to eliminate exclusion barriers that perpetuate poverty and inequality:"}},{"t":"item","zona":"cuerpo","texto":{"es":"Inclusión Social: Implementación de la Política de Inclusión, Equidad y Diversidad.","en":"Social Inclusion: Implementation of the Policy of Inclusion, Equity, and Diversity."}},{"t":"item","zona":"cuerpo","texto":{"es":"Atención a la Discapacidad: Eventos de sensibilización y apoyo integral, como la Cabalgata Inclusiva con futuros fisioterapeutas, que refuerza el apoyo emocional y social a personas con discapacidad y sus familias.","en":"Disability Care: Awareness events and comprehensive support, such as the Inclusive Horseback Ride with future physical therapists, which reinforces emotional and social support for people with disabilities and their families."}},{"t":"item","zona":"cuerpo","texto":{"es":"Investigación Aplicada: Proyecto destacado en congreso internacional al co-diseñar soluciones de Accesibilidad Comunicativa Universal con personas con discapacidad visual, física y auditiva en Valledupar. Investigación del programa de Fisioterapia sobre barreras para la inclusión de estudiantes con discapacidad obtuvo el primer puesto en simposio regional.","en":"Applied Research: Project featured at international congress co-designing Universal Communicative Accessibility solutions with people with visual, physical, and hearing disabilities in Valledupar. Research from the Physical Therapy program on barriers to inclusion of students with disabilities won first place at a regional symposium."}},{"t":"item","zona":"cuerpo","texto":{"es":"Formación de Líderes para la Paz: Alianza con la Universidad para la Paz (UPEACE) para formar líderes con enfoque en desarrollo humano integral, transformación pacífica de conflictos, desarrollo sustentable y sostenible, con elementos de equidad de género y no discriminación, incluyendo temáticas sobre la lucha contra la pobreza.","en":"Training Leaders for Peace: Alliance with the University for Peace (UPEACE) to train leaders with a focus on integral human development, peaceful transformation of conflicts, sustainable development, with elements of gender equity and non-discrimination, including themes on the fight against poverty."}}]},{"titulo":{"es":"Asequibilidad y Financiamiento Educativo","en":"Affordability and Educational Financing"},"piezas":[{"t":"parrafo","zona":"cuerpo","texto":{"es":"Para garantizar que la falta de recursos no sea una barrera, la UDES ofrece diversas facilidades financieras, fundamentales para la movilidad social y la mitigación de la pobreza futura:","en":"To ensure that lack of resources is not a barrier, UDES offers various financial facilities, fundamental for social mobility and the mitigation of future poverty:"}},{"t":"item","zona":"cuerpo","texto":{"es":"Diversidad de entidades financieras aliadas y portafolios de crédito educativo para impulsar y facilitar el acceso a una educación de calidad.","en":"Diversity of allied financial institutions and educational credit portfolios to promote and facilitate access to quality education."}},{"t":"item","zona":"cuerpo","texto":{"es":"Promoción de la inclusión financiera y crediticia y apoyo al emprendimiento local mediante alianzas estratégicas, como la fortalecida con el Fondo Nacional de Garantías (FNG).","en":"Promotion of financial and credit inclusion and support for local entrepreneurship through strategic alliances, such as the strengthened one with the National Guarantee Fund (FNG)."}},{"t":"item","zona":"cuerpo","texto":{"es":"Convenios interinstitucionales con beneficios, como el acuerdo con el SENA para que sus graduados continúen su formación en la UDES con descuentos y homologaciones.","en":"Interinstitutional agreements with benefits, such as the agreement with SENA for its graduates to continue their education at UDES with discounts and course equivalencies."}},{"t":"item","zona":"cuerpo","texto":{"es":"Descuentos a miembros de entidades aliadas como CORDEINCALS y Campuslands.","en":"Discounts for members of allied entities such as CORDEINCALS and Campuslands."}}]},{"titulo":{"es":"Reconocimiento Global","en":"Global Recognition"},"piezas":[{"t":"parrafo","zona":"cuerpo","texto":{"es":"El compromiso de la UDES con la sostenibilidad y la calidad, aspectos que refuerzan su lucha contra la pobreza al asegurar una formación pertinente, ha sido reconocido internacionalmente:","en":"UDES's commitment to sustainability and quality, aspects that reinforce its fight against poverty by ensuring relevant education, has been internationally recognized:"}},{"t":"item","zona":"cuerpo","texto":{"es":"Acreditación institucional internacional multicampus otorgada por la Education Quality Accreditation Agency (EQUAA), que evalúa la inclusión social como aspecto clave.","en":"International multicampus institutional accreditation granted by the Education Quality Accreditation Agency (EQUAA), which evaluates social inclusion as a key aspect."}},{"t":"item","zona":"cuerpo","texto":{"es":"Destacada en rankings internacionales, incluyendo reconocimientos por su trabajo hacia el logro de los Objetivos de Desarrollo Sostenible (ODS).","en":"Featured in international rankings, including recognitions for its work toward achieving the Sustainable Development Goals (SDGs)."}},{"t":"item","zona":"cuerpo","texto":{"es":"Seleccionada como socio en el proyecto ACT4SDGS para incorporar los ODS en la enseñanza y los planes de estudio en universidades latinoamericanas, promoviendo la inclusión, la igualdad y la educación de calidad.","en":"Selected as a partner in the ACT4SDGS project to incorporate SDGs in teaching and curricula in Latin American universities, promoting inclusion, equality, and quality education."}}]},{"titulo":{"es":"Tres Ejes de Impacto UDES: Fin a la Pobreza (ODS 1)","en":"Three UDES Impact Pillars: Ending Poverty (SDG 1)"},"piezas":[{"t":"titulo","zona":"cuerpo","nivel":3,"texto":{"es":"Extensión Social y Bienestar Básico","en":"Social Outreach and Basic Well-being"}},{"t":"parrafo","zona":"cuerpo","texto":{"es":"El programa MIUDES ofrece apoyo integral a comunidades vulnerables (Los Colorados) mediante Investigación Acción Participativa. Sus acciones incluyen planes padrino para seguridad alimentaria e higiene, consulta médica, primeros auxilios psicológicos y promoción de lactancia materna.","en":"The MIUDES program provides comprehensive support to vulnerable communities (Los Colorados) through Participatory Action Research. Its actions include sponsor plans for food and hygiene security, medical consultation, psychological first aid, and breastfeeding promotion."}},{"t":"titulo","zona":"cuerpo","nivel":3,"texto":{"es":"Empoderamiento Económico y Capacitación","en":"Economic Empowerment and Training"}},{"t":"parrafo","zona":"cuerpo","texto":{"es":"UDES fortalece unidades productivas y promueve el emprendimiento. Esto incluye el Diplomado de Economía Popular para unidades productivas vulnerables y el proyecto \"Maquilando Felicidad\" en Piedecuesta, capacitando a jóvenes y mujeres en oficios para generar ingresos sostenibles [136, 459, 464, HC].","en":"UDES strengthens productive units and promotes entrepreneurship. This includes the Popular Economy Diploma for vulnerable productive units and the \"Maquilando Felicidad\" project in Piedecuesta, training youth and women in trades to generate sustainable incomes [136, 459, 464, HC]."}},{"t":"titulo","zona":"cuerpo","nivel":3,"texto":{"es":"Inclusión y Acceso a la Educación","en":"Inclusion and Access to Education"}},{"t":"parrafo","zona":"cuerpo","texto":{"es":"UDES implementa su Política de Inclusión, Equidad y Diversidad para eliminar barreras. Fomenta la accesibilidad (ej. Braille) y forma líderes con UPEACE en temas de paz, no discriminación y lucha contra la pobreza, esenciales para el desarrollo humano, sustentable y la movilidad social.","en":"UDES implements its Policy of Inclusion, Equity, and Diversity to remove barriers. It promotes accessibility (e.g., Braille) and trains leaders with UPEACE on peace, non-discrimination, and the fight against poverty—essential for human development, sustainability, and social mobility."}}]}],"bloques":[{"sec":"tesis","text":"La Salud y Bienestar (ODS 3) representa el compromiso de la Universidad de Santander (UDES) con garantizar vidas saludables y promover el bienestar para todos en todas las edades. La UDES aborda este objetivo mediante la formación de profesionales de la salud de alta calidad, la investigación aplicada en salud pública, y la extensión social que impacta directamente en las comunidades. Desde la respuesta a crisis sanitarias hasta la promoción de estilos de vida saludables en el campus, la UDES materializa su compromiso con el bienestar integral de la sociedad.","text_en":"Good Health and Well-Being (SDG 3) represents the Universidad de Santander (UDES) commitment to ensuring healthy lives and promoting well-being for all at all ages. The UDES addresses this objective through training high-quality health professionals, applied public health research, and social outreach that directly impacts communities. From responding to health crises to promoting healthy lifestyles on campus, the UDES materializes its commitment to the comprehensive well-being of society.","pos":1,"enabled":true,"warn":null},{"sec":"cifras","text":"UDES: Impulsando la Salud en la Región.","text_en":"UDES: Driving Health in the Region.","figs":[{"v":"4.849","label":"Graduados Totales","src":"Informe 2025","v_en":"4,849","label_en":"Total Graduates","note":"En el período evaluado, la UDES entregó al país y al mundo 4.849 profesionales listos para transformar la sociedad. ¡Una muestra de nuestra productividad académica y el impacto de nuestros egresados en diversos campos!","note_en":"During the evaluated period, UDES delivered 4,849 professionals ready to transform society to the country and the world. A testament to our academic productivity and the impact of our graduates across diverse fields!"},{"v":"835","label":"Profesionales de la Salud","src":"Informe 2025","v_en":"835","label_en":"Health Professionals","note":"De ese gran total, 835 nuevos profesionales se graduaron de nuestras áreas de la salud. Esto refleja el compromiso de la UDES para fortalecer el sistema de salud y atender las necesidades más apremiantes de nuestras comunidades.","note_en":"From that grand total, 835 new professionals graduated from our health programs. This reflects UDES's commitment to strengthening the health system and addressing the most pressing needs of our communities."},{"v":"17,22 %","label":"Concentración Estratégica","src":"Informe 2025","v_en":"17.22%","label_en":"Strategic Concentration","note":"¡El 17,22 % de nuestros graduados son profesionales de la salud! Esta alta proporción (≈0,1722) subraya la vocación de servicio y la alta inversión de la UDES en programas de calidad que forman a los líderes del sector salud. Estamos sembrando bienestar.","note_en":"17.22% of our graduates are health professionals! This high proportion (≈0.1722) underscores UDES's service vocation and strong investment in quality programs that train leaders in the health sector. We are sowing well-being."}],"pos":2,"enabled":true,"warn":null},{"sec":"hicimos","text":"Resumen Ejecutivo. La Universidad de Santander (UDES) demuestra un compromiso central con el Objetivo de Desarrollo Sostenible (ODS) 1, Fin de la Pobreza, articulando sus funciones sustantivas para impulsar la transformación social en sus áreas de influencia. Este compromiso se materializa en estrategias que buscan la inclusión de comunidades vulnerables y el desarrollo económico regional. La UDES utiliza la educación y la extensión como herramientas clave, por ejemplo, mediante la Escuela Empresarial Udeista, que ofrece el Diplomado de Economía Popular para fortalecer unidades productivas. Asimismo, el proyecto \"Maquilando Felicidad\" busca el empoderamiento económico de jóvenes y mujeres de Piedecuesta a través de programas de formación integral.","text_en":"Executive Summary. The Universidad de Santander (UDES) demonstrates a core commitment to Sustainable Development Goal (SDG) 1, No Poverty, aligning its substantive functions to drive social transformation in its areas of influence. This commitment materializes through strategies aimed at including vulnerable communities and promoting regional economic development. Education and outreach serve as key tools—for example, the Udeista Business School’s Popular Economy Diploma strengthens productive units. Likewise, the \"Maquilando Felicidad\" project fosters the economic empowerment of young people and women in Piedecuesta through comprehensive training programs.","encabezado":"Resumen Ejecutivo","pos":3,"enabled":true,"warn":null},{"sec":"hicimos","text":"La estrategia de UDES para el ODS 1 abarca la dignificación a través de la inclusión social, la equidad y el bienestar comunitario. El Modelo Interprofesional (MIUDES), por ejemplo, apoya directamente a poblaciones vulnerables, incluyendo acciones cruciales de salud, prevención (como la promoción de la lactancia materna para la seguridad alimentaria y nutricional), y estructurando planes de apoyo para fortalecer los componentes alimentario e higiénico en las familias. Además, la UDES ha desarrollado su Política de Inclusión, Equidad y Diversidad, y forma líderes a través de alianzas con la Universidad para la Paz (UPEACE), incluyendo módulos sobre la lucha contra la pobreza, reconociendo que la equidad y la no discriminación son fundamentales para el desarrollo sustentable y la paz.","text_en":"UDES’s SDG 1 strategy encompasses dignity through social inclusion, equity, and community well-being. The Interprofessional Model (MIUDES) directly supports vulnerable populations with crucial health and prevention actions (such as promoting breastfeeding for food and nutrition security) and by structuring support plans to strengthen food and hygiene components in families. Additionally, UDES has developed its Policy of Inclusion, Equity, and Diversity and trains leaders through alliances with the University for Peace (UPEACE), including modules on the fight against poverty, recognizing that equity and non-discrimination are fundamental to sustainable development and peace.","pos":4,"enabled":false,"warn":"Texto repetido de otro ODS en el informe 2025: revisar antes de usar."},{"sec":"hicimos","text":"UDES: Impulsando la Salud en la Región. ¡Un Logro de Impacto Global! La Universidad de Santander (UDES) se destaca en el prestigioso THE Impact Rankings, reafirmando nuestro compromiso con la salud y el bienestar.","text_en":"UDES: Driving Health in the Region. A Global Impact Achievement! The University of Santander (UDES) stands out in the prestigious THE Impact Rankings, reaffirming our commitment to health and well-being.","encabezado":"UDES: Impulsando la Salud en la Región","pos":5,"enabled":true,"warn":null},{"sec":"hicimos","text":"Desarrollo Económico y Formación para la Prosperidad. La UDES promueve el crecimiento económico inclusivo y el emprendimiento como herramientas clave para salir de la pobreza:","text_en":"Economic Development and Training for Prosperity. UDES promotes inclusive economic growth and entrepreneurship as key tools to overcome poverty:","encabezado":"Desarrollo Económico y Formación para la Prosperidad","pos":6,"enabled":false,"warn":"Texto repetido de otro ODS en el informe 2025: revisar antes de usar."},{"sec":"hicimos","text":"Impulso Empresarial y Mipyme. Organización de ferias internacionales de emprendimiento (\"Yo Emprendo\") para fortalecer habilidades y potenciar el alcance de iniciativas. Alianzas para fortalecer el sector empresarial y las Mipyme, como el convenio con la Cámara de Comercio de Bucaramanga para capacitar tenderos. VI Congreso Internacional de la Facultad de Ciencias Económicas, enfocado en innovación empresarial para potenciar las Mipyme de la región. Apoyo a artesanos y emprendedores mediante eventos como la Feria Homenaje al Artesano, que buscan el desarrollo sostenible económico y social en la región.","text_en":"Business Promotion and SMEs. Organization of international entrepreneurship fairs (\"Yo Emprendo\") to strengthen skills and enhance the reach of initiatives. Alliances to strengthen the business sector and SMEs, such as the agreement with the Bucaramanga Chamber of Commerce to train shopkeepers. VI International Congress of the Faculty of Economic Sciences, focused on business innovation to boost regional SMEs. Support for artisans and entrepreneurs through events such as the Artisan Tribute Fair, seeking sustainable economic and social development in the region.","encabezado":"Impulso Empresarial y Mipyme","pos":7,"enabled":false,"warn":"Texto repetido de otro ODS en el informe 2025: revisar antes de usar."},{"sec":"hicimos","text":"Articulación con Gobiernos Locales. La UDES es miembro del Consejo Territorial de Planeación (CTP) en Bucaramanga, aportando propuestas, metas e indicadores para el Plan de Desarrollo. Alianzas estratégicas con la Gobernación de Santander y las Alcaldías de Bucaramanga, Piedecuesta y Girón para alinear proyectos en el Plan de Desarrollo Municipal y Departamental. Proyectos estratégicos que impulsan el desarrollo económico, como el fortalecimiento de clústeres productivos y la masificación de la educación.","text_en":"Local Government Coordination. UDES is a member of the Territorial Planning Council (CTP) in Bucaramanga, contributing proposals, goals, and indicators for the Development Plan. Strategic alliances with the Government of Santander and the municipalities of Bucaramanga, Piedecuesta, and Girón to align projects in the Municipal and Departmental Development Plan. Strategic projects that promote economic development, such as strengthening productive clusters and expanding education.","encabezado":"Articulación con Gobiernos Locales","pos":8,"enabled":false,"warn":"Texto repetido de otro ODS en el informe 2025: revisar antes de usar."},{"sec":"hicimos","text":"Inclusión y No Discriminación. La UDES trabaja activamente para eliminar las barreras de exclusión que perpetúan la pobreza y la desigualdad: Inclusión Social: Implementación de la Política de Inclusión, Equidad y Diversidad. Atención a la Discapacidad: Eventos de sensibilización y apoyo integral, como la Cabalgata Inclusiva con futuros fisioterapeutas, que refuerza el apoyo emocional y social a personas con discapacidad y sus familias. Investigación Aplicada: Proyecto destacado en congreso internacional al co-diseñar soluciones de Accesibilidad Comunicativa Universal con personas con discapacidad visual, física y auditiva en Valledupar. Investigación del programa de Fisioterapia sobre barreras para la inclusión de estudiantes con discapacidad obtuvo el primer puesto en simposio regional. Formación de Líderes para la Paz: Alianza con la Universidad para la Paz (UPEACE) para formar líderes con enfoque en desarrollo humano integral, transformación pacífica de conflictos, desarrollo sustentable y sostenible, con elementos de equidad de género y no discriminación, incluyendo temáticas sobre la lucha contra la pobreza.","text_en":"Inclusion and Non-Discrimination. UDES actively works to eliminate exclusion barriers that perpetuate poverty and inequality: Social Inclusion: Implementation of the Policy of Inclusion, Equity, and Diversity. Disability Care: Awareness events and comprehensive support, such as the Inclusive Horseback Ride with future physical therapists, which reinforces emotional and social support for people with disabilities and their families. Applied Research: Project featured at international congress co-designing Universal Communicative Accessibility solutions with people with visual, physical, and hearing disabilities in Valledupar. Research from the Physical Therapy program on barriers to inclusion of students with disabilities won first place at a regional symposium. Training Leaders for Peace: Alliance with the University for Peace (UPEACE) to train leaders with a focus on integral human development, peaceful transformation of conflicts, sustainable development, with elements of gender equity and non-discrimination, including themes on the fight against poverty.","encabezado":"Inclusión y No Discriminación","pos":9,"enabled":false,"warn":"Texto repetido de otro ODS en el informe 2025: revisar antes de usar."},{"sec":"hicimos","text":"Asequibilidad y Financiamiento Educativo. Para garantizar que la falta de recursos no sea una barrera, la UDES ofrece diversas facilidades financieras, fundamentales para la movilidad social y la mitigación de la pobreza futura: Diversidad de entidades financieras aliadas y portafolios de crédito educativo para impulsar y facilitar el acceso a una educación de calidad. Promoción de la inclusión financiera y crediticia y apoyo al emprendimiento local mediante alianzas estratégicas, como la fortalecida con el Fondo Nacional de Garantías (FNG). Convenios interinstitucionales con beneficios, como el acuerdo con el SENA para que sus graduados continúen su formación en la UDES con descuentos y homologaciones. Descuentos a miembros de entidades aliadas como CORDEINCALS y Campuslands.","text_en":"Affordability and Educational Financing. To ensure that lack of resources is not a barrier, UDES offers various financial facilities, fundamental for social mobility and the mitigation of future poverty: Diversity of allied financial institutions and educational credit portfolios to promote and facilitate access to quality education. Promotion of financial and credit inclusion and support for local entrepreneurship through strategic alliances, such as the strengthened one with the National Guarantee Fund (FNG). Interinstitutional agreements with benefits, such as the agreement with SENA for its graduates to continue their education at UDES with discounts and course equivalencies. Discounts for members of allied entities such as CORDEINCALS and Campuslands.","encabezado":"Asequibilidad y Financiamiento Educativo","pos":10,"enabled":false,"warn":"Texto repetido de otro ODS en el informe 2025: revisar antes de usar."},{"sec":"hicimos","text":"Reconocimiento Global. El compromiso de la UDES con la sostenibilidad y la calidad, aspectos que refuerzan su lucha contra la pobreza al asegurar una formación pertinente, ha sido reconocido internacionalmente: Acreditación institucional internacional multicampus otorgada por la Education Quality Accreditation Agency (EQUAA), que evalúa la inclusión social como aspecto clave. Destacada en rankings internacionales, incluyendo reconocimientos por su trabajo hacia el logro de los Objetivos de Desarrollo Sostenible (ODS). Seleccionada como socio en el proyecto ACT4SDGS para incorporar los ODS en la enseñanza y los planes de estudio en universidades latinoamericanas, promoviendo la inclusión, la igualdad y la educación de calidad.","text_en":"Global Recognition. UDES's commitment to sustainability and quality, aspects that reinforce its fight against poverty by ensuring relevant education, has been internationally recognized: International multicampus institutional accreditation granted by the Education Quality Accreditation Agency (EQUAA), which evaluates social inclusion as a key aspect. Featured in international rankings, including recognitions for its work toward achieving the Sustainable Development Goals (SDGs). Selected as a partner in the ACT4SDGS project to incorporate SDGs in teaching and curricula in Latin American universities, promoting inclusion, equality, and quality education.","encabezado":"Reconocimiento Global","pos":11,"enabled":false,"warn":"Texto repetido de otro ODS en el informe 2025: revisar antes de usar."},{"sec":"hicimos","text":"Extensión Social y Bienestar Básico. El programa MIUDES ofrece apoyo integral a comunidades vulnerables (Los Colorados) mediante Investigación Acción Participativa. Sus acciones incluyen planes padrino para seguridad alimentaria e higiene, consulta médica, primeros auxilios psicológicos y promoción de lactancia materna.","text_en":"Social Outreach and Basic Well-being. The MIUDES program provides comprehensive support to vulnerable communities (Los Colorados) through Participatory Action Research. Its actions include sponsor plans for food and hygiene security, medical consultation, psychological first aid, and breastfeeding promotion.","encabezado":"Extensión Social y Bienestar Básico","pos":12,"enabled":false,"warn":"Texto repetido de otro ODS en el informe 2025: revisar antes de usar."},{"sec":"hicimos","text":"Empoderamiento Económico y Capacitación. UDES fortalece unidades productivas y promueve el emprendimiento. Esto incluye el Diplomado de Economía Popular para unidades productivas vulnerables y el proyecto \"Maquilando Felicidad\" en Piedecuesta, capacitando a jóvenes y mujeres en oficios para generar ingresos sostenibles [136, 459, 464, HC].","text_en":"Economic Empowerment and Training. UDES strengthens productive units and promotes entrepreneurship. This includes the Popular Economy Diploma for vulnerable productive units and the \"Maquilando Felicidad\" project in Piedecuesta, training youth and women in trades to generate sustainable incomes [136, 459, 464, HC].","encabezado":"Empoderamiento Económico y Capacitación","pos":13,"enabled":false,"warn":"Texto repetido de otro ODS en el informe 2025: revisar antes de usar."},{"sec":"hicimos","text":"Inclusión y Acceso a la Educación. UDES implementa su Política de Inclusión, Equidad y Diversidad para eliminar barreras. Fomenta la accesibilidad (ej. Braille) y forma líderes con UPEACE en temas de paz, no discriminación y lucha contra la pobreza, esenciales para el desarrollo humano, sustentable y la movilidad social.","text_en":"Inclusion and Access to Education. UDES implements its Policy of Inclusion, Equity, and Diversity to remove barriers. It promotes accessibility (e.g., Braille) and trains leaders with UPEACE on peace, non-discrimination, and the fight against poverty—essential for human development, sustainability, and social mobility.","encabezado":"Inclusión y Acceso a la Educación","pos":14,"enabled":false,"warn":"Texto repetido de otro ODS en el informe 2025: revisar antes de usar."},{"sec":"proyectos","text":"Proyectos de Extensión y Servicio Comunitario. La UDES utiliza su extensión social para impactar directamente a comunidades en situación de vulnerabilidad, abordando múltiples dimensiones de la pobreza:","text_en":"Outreach Projects and Community Service. UDES uses its social outreach to directly impact communities in vulnerable situations, addressing multiple dimensions of poverty:","encabezado":"Proyectos de Extensión y Servicio Comunitario","pos":15,"enabled":false,"warn":"Texto repetido de otro ODS en el informe 2025: revisar antes de usar."},{"sec":"proyectos","text":"Modelo Interprofesional de la UDES (MIUDES). Realiza acciones a nivel familiar, individual y comunitario en barrios como Los Colorados, en la comuna 1 del norte de Bucaramanga. Basado en la metodología Investigación Acción Participativa, ofrece acompañamiento interprofesional a poblaciones vulnerables. Demostró un impacto crucial durante la emergencia sanitaria por COVID-19 (2020-2021), diseñando estrategias que incluyeron consulta médica, primeros auxilios psicológicos, pedagogía de prevención y un plan padrino para fortalecer el componente alimentario e higiénico. Sus mesas de trabajo abordan salud, saneamiento y ambiente, gobernanza, habilidades, y tecnología y comunicaciones. Los estudiantes realizan proyectos de construcción de paz y tejido social en la comunidad.","text_en":"UDES Interprofessional Model (MIUDES). Conducts actions at family, individual, and community levels in neighborhoods such as Los Colorados, in commune 1 of northern Bucaramanga. Based on Participatory Action Research methodology, offers interprofessional support to vulnerable populations. Demonstrated crucial impact during the COVID-19 health emergency (2020-2021), designing strategies including medical consultation, psychological first aid, prevention pedagogy, and a sponsor plan to strengthen food and hygiene components. Working groups address health, sanitation and environment, governance, skills, and technology and communications. Students carry out peace-building and social fabric projects in the community.","encabezado":"Modelo Interprofesional de la UDES (MIUDES)","pos":16,"enabled":false,"warn":"Texto repetido de otro ODS en el informe 2025: revisar antes de usar."},{"sec":"proyectos","text":"Proyecto \"Maquilando Felicidad\" (Piedecuesta). Liderado por la UDES en colaboración con la Fundación Marie Poussepin en comunidades vulnerables de Piedecuesta (sector Barro Blanco). Enfoque directo en la mitigación de la pobreza mediante el empoderamiento económico, capacitando a 25 jóvenes y mujeres en panadería y chocolatería para generar ingresos y emprender negocios. Incluye servicios de Salud Integral (atención a población infantil, madres gestantes, adultos mayores) y talleres de bienestar emocional y prevención de violencias de género. Involucra programas de Ingenierías, Ciencias Médicas y de la Salud, Ciencias Administrativas y Sociales.","text_en":"\"Maquilando Felicidad\" Project (Piedecuesta). Led by UDES in collaboration with the Marie Poussepin Foundation in vulnerable communities of Piedecuesta (Barro Blanco sector). Direct focus on poverty mitigation through economic empowerment, training 25 young people and women in bakery and chocolate-making to generate income and start businesses. Includes Comprehensive Health services (care for children, pregnant mothers, elderly) and workshops on emotional well-being and prevention of gender-based violence. Involves programs from Engineering, Medical and Health Sciences, Administrative and Social Sciences.","encabezado":"Proyecto \"Maquilando Felicidad\" (Piedecuesta)","pos":17,"enabled":false,"warn":"Texto repetido de otro ODS en el informe 2025: revisar antes de usar."},{"sec":"proyectos","text":"Apoyo a Población en Situación de Vulnerabilidad Social. Estudiantes de la UDES contribuyen a mejorar la calidad de vida de habitantes de calle y sus familias en Bucaramanga a través de la Fundación Posada del Peregrino, proporcionando alimento, vestido y educación para los niños. El proyecto \"El Recolector\" en Hogares Crea (rehabilitación por consumo de sustancias) fomenta la seguridad alimentaria y el emprendimiento mediante huertas caseras, funcionando también como terapia ocupacional.","text_en":"Support for Socially Vulnerable Populations. UDES students contribute to improving the quality of life of homeless people and their families in Bucaramanga through the Posada del Peregrino Foundation, providing food, clothing, and education for children. \"El Recolector\" project at Hogares Crea (substance abuse rehabilitation) promotes food security and entrepreneurship through home gardens, also functioning as occupational therapy.","encabezado":"Apoyo a Población en Situación de Vulnerabilidad Social","pos":18,"enabled":false,"warn":"Texto repetido de otro ODS en el informe 2025: revisar antes de usar."},{"sec":"proyectos","text":"Diplomado de Economía Popular. La Escuela Empresarial Udeista ofrece un diplomado en economía popular para fortalecer unidades productivas. Beneficia a participantes que han firmado el acuerdo de paz o se han acogido a la Ley de Justicia y Paz, incluyendo personas de Santander y el Magdalena Medio.","text_en":"Popular Economy Diploma Program. The Udeista Business School offers a diploma in popular economy to strengthen productive units. Benefits participants who have signed the peace agreement or have availed themselves of the Justice and Peace Law, including people from Santander and the Magdalena Medio.","encabezado":"Diplomado de Economía Popular","pos":19,"enabled":false,"warn":"Texto repetido de otro ODS en el informe 2025: revisar antes de usar."}],"conteo":{"tesis":1,"cifras":1,"hicimos":12,"proyectos":5,"viene":0,"cifras_figs":3,"videos":0,"enlaces":0,"copiados":15,"deshabilitados":15},"rarezas":["Las cifras no tienen frase que las presente: el bloque de cifras lleva el título de su sección.","Sin «próximos pasos» en el HTML: el informe no tiene sección «viene».","15 bloque(s) idénticos a los del ODS 1: se importan deshabilitados, con aviso."]}$ods_json$::jsonb,
$ods_html$<!DOCTYPE html>
<html lang="es">
<head>
  <meta charset="UTF-8" />
  <meta name="viewport" content="width=device-width, initial-scale=1.0" />
  <title>ODS 3 · Salud y Bienestar | Informe</title>
  <meta name="description" content="Informe profesional ODS 3 (Salud y Bienestar) con cifras dinámicas y noticias. Español e Inglés." />
  <!-- Fuente Inter para un look moderno -->
  <link href="https://fonts.googleapis.com/css2?family=Inter:wght@300;400;500;600;700;800&display=swap" rel="stylesheet">
  <style>
    :root {
      --sdg3-green: #4C9F38;
      --sdg3-dark: #3a7a2b;
      --sdg3-light: #e3f4de;
      --text-primary: #2c3e50;
      --text-secondary: #546e7a;
      --text-muted: #7f8c9a;
      --bg-light: #fafbfc;
      --bg-white: #ffffff;
      --border-light: #e8eaed;
      --border-subtle: #f1f3f5;
      --shadow-sm: 0 1px 3px rgba(0,0,0,0.04);
      --shadow-md: 0 4px 12px rgba(0,0,0,0.06);
      --shadow-lg: 0 8px 24px rgba(0,0,0,0.08);
    }

    /* Reset & Base */
    * { box-sizing: border-box; margin: 0; padding: 0; }
    html { scroll-behavior: smooth; }
    body { 
      font-family: 'Inter', -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, 'Helvetica Neue', Arial, sans-serif;
      line-height: 1.7;
      color: var(--text-primary);
      background: var(--bg-white);
      font-size: 16px;
      -webkit-font-smoothing: antialiased;
      -moz-osx-font-smoothing: grayscale;
    }

    /* Typography */
    h1, h2, h3, h4, h5, h6 { 
      font-family: 'Inter', -apple-system, BlinkMacSystemFont, 'Segoe UI', sans-serif;
      font-weight: 700;
      line-height: 1.3;
      letter-spacing: -0.02em;
      color: var(--text-primary);
    }
    
    p { 
      text-align: justify;
      hyphens: auto;
      word-spacing: 0.05em;
      margin-bottom: 1em;
    }
    
    p:last-child { margin-bottom: 0; }
    
    ul, ol { 
      text-align: justify;
      padding-left: 1.5em;
      margin-bottom: 1em;
    }
    
    li { margin-bottom: 0.5em; line-height: 1.7; }
    li:last-child { margin-bottom: 0; }

    .container { 
      max-width: 1160px; 
      margin: 0 auto; 
      padding: 0 28px; 
    }
    .lang-switch button {
      appearance: none;
      border: none;
      background: transparent;
      color: var(--text-secondary);
      padding: 8px 16px;
      border-radius: 7px;
      cursor: pointer;
      font-weight: 600;
      font-size: 14px;
      transition: all 0.2s ease;
      letter-spacing: 0.3px;
    }
    
    .lang-switch button:hover { background: rgba(0,0,0,0.04); }
    .lang-switch button.active { 
      background: var(--bg-white);
      color: var(--sdg3-green);
      box-shadow: var(--shadow-sm);
    }

    /* Barra de Navegación ODS - Línea delgada que se expande */
    .sdg-navbar {
      position: fixed;
      top: 0;
      left: 0;
      width: 100%;
      height: 8px; /* Un poco más ancha para mostrar el texto */
      display: flex;
      z-index: 1000;
      background: transparent;
    }

    .sdg-nav-item {
      flex: 1;
      height: 8px; /* Sincronizar con navbar */
      cursor: pointer;
      position: relative;
      transition: all 0.4s cubic-bezier(0.4, 0, 0.2, 1);
      text-decoration: none;
      display: flex;
      align-items: center;
      justify-content: center;
      overflow: hidden;
    }
    
    /* Texto "ODS N" siempre visible sobre la barra de color */
    .sdg-nav-item::before {
      content: "ODS " attr(data-sdg);
      position: absolute;
      top: 50%;
      left: 50%;
      transform: translate(-50%, -50%);
      color: #fff;
      font-size: 10px;
      font-weight: 700;
      letter-spacing: 0.5px;
      z-index: 2;
      opacity: 1;
      transition: opacity 0.3s ease;
      pointer-events: none;
      text-shadow: 0 1px 2px rgba(0,0,0,0.2);
    }
    
    /* Ocultar el texto cuando se expande la card */
    .sdg-nav-item:hover::before {
      opacity: 0;
    }

    .sdg-nav-item:hover {
      height: 320px;
      box-shadow: 0 4px 20px rgba(0, 0, 0, 0.15);
    }

    /* Card que se despliega */
    .sdg-card {
      width: 100%;
      height: 100%;
      background: white;
      display: flex;
      flex-direction: column;
      opacity: 0;
      transition: opacity 0.3s ease 0.15s;
    }

    .sdg-nav-item:hover .sdg-card {
      opacity: 1;
    }

    .sdg-card-image {
      width: 100%;
      height: 220px;
      object-fit: contain;
      display: block;
      background: white;
      padding: 8px;
    }

    .sdg-card-content {
      padding: 16px;
      text-align: center;
      flex: 1;
      display: flex;
      flex-direction: column;
      justify-content: center;
      align-items: center;
      gap: 4px;
    }

    .sdg-card-number {
      font-size: 12px;
      font-weight: 700;
      text-transform: uppercase;
      letter-spacing: 1px;
      opacity: 0.9;
    }

    .sdg-card-title {
      font-size: 14px;
      font-weight: 600;
      color: #1a1a1a;
      margin: 0;
      line-height: 1.3;
    }

    /* Idiomas para la barra: usa el atributo lang del <html> */
    html[lang="es"] .lang-en { display: none !important; }
    html[lang="en"] .lang-es { display: none !important; }

    /* Colores de cada ODS (heredados de paleta global) */
    .sdg-1 { background: #E5243B; }
    .sdg-2 { background: #DDA63A; }
    .sdg-3 { background: #4C9F38; }
    .sdg-4 { background: #C5192D; }
    .sdg-5 { background: #FF3A21; }
    .sdg-6 { background: #26BDE2; }
    .sdg-7 { background: #FCC30B; }
    .sdg-8 { background: #A21942; }
    .sdg-9 { background: #FD6925; }
    .sdg-10 { background: #DD1367; }
    .sdg-11 { background: #FD9D24; }
    .sdg-12 { background: #BF8B2E; }
    .sdg-13 { background: #3F7E44; }
    .sdg-14 { background: #0A97D9; }
    .sdg-15 { background: #56C02B; }
    .sdg-16 { background: #00689D; }
    .sdg-17 { background: #19486A; }

    /* Responsive */
    @media (max-width: 768px) {
      .sdg-nav-item:hover { height: 280px; }
      .sdg-card-image { height: 180px; padding: 6px; }
      .sdg-card-content { padding: 12px; }
      .sdg-card-number { font-size: 11px; }
      .sdg-card-title { font-size: 12px; }
    }

    /* Hero Section */
    .hero { 
      padding: 88px 0 72px;
      background: radial-gradient(circle at 50% 0%, var(--sdg3-light) 0%, #ffffff 65%);
      border-bottom: 1px solid var(--border-light);
      position: relative;
      overflow: hidden;
      clip-path: polygon(0 0, 100% 0, 100% 92%, 50% 100%, 0 92%);
    }
    
    .eyebrow { 
      color: var(--sdg3-green);
      text-transform: uppercase;
      font-weight: 700;
      letter-spacing: 0.12em;
      font-size: 12px;
      font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', sans-serif;
      margin-bottom: 12px;
      display: inline-block;
    }
    
    .hero h1 { 
      font-size: clamp(32px, 5vw, 52px);
      line-height: 1.15;
      margin: 0 0 16px 0;
      color: var(--text-primary);
    }
    
    .subtitle { 
      color: var(--text-secondary);
      font-size: 19px;
      line-height: 1.6;
      max-width: 720px;
      text-align: justify;
    }
    
    .hero-illustration {
      width: 100%;
      height: auto;
      max-width: 360px;
      margin: 0 auto;
      border-radius: 16px;
      display: block;
    }

    /* Section Styling */
    section { 
      padding: 64px 0;
      background: transparent;
    }
    
    section:nth-child(even) { background: transparent; }
    
    .section-title { 
      font-size: clamp(26px, 3.8vw, 36px);
      margin: 0 0 8px 0;
      font-weight: 700;
    }
    .section-title .icon {
      width: 28px;
      height: 28px;
      vertical-align: -4px;
      margin-right: 10px;
    }
    .section-title .icon circle,
    .section-title .icon line,
    .section-title .icon path {
      stroke: var(--sdg3-green);
      fill: none;
      stroke-width: 2;
      stroke-linecap: round;
      stroke-linejoin: round;
    }
    
    .section-rule { 
      width: 64px;
      height: 4px;
      background: linear-gradient(90deg, var(--sdg3-green) 0%, var(--sdg3-dark) 100%);
      margin-bottom: 32px;
      border-radius: 2px;
    }
    
    .subsection-title {
      font-size: 19px;
      font-weight: 700;
      color: var(--text-primary);
      margin: 24px 0 12px 0;
      font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', sans-serif;
    }

    /* Layouts */
    .grid-2 { 
      display: grid;
      grid-template-columns: 1fr 1fr;
      gap: 48px;
      align-items: start;
    }
    
    .grid-3 { 
      display: grid;
      grid-template-columns: repeat(3, 1fr);
      gap: 28px;
    }

    /* Card Styling */
    .card { 
      background: var(--bg-white);
      border: 1px solid var(--border-subtle);
      border-radius: 12px;
      padding: 32px;
      box-shadow: var(--shadow-sm);
      transition: all 0.3s ease;
    }
    
    .card:hover { 
      box-shadow: var(--shadow-md);
      border-color: var(--border-light);
    }
    
    .muted { 
      color: var(--text-muted);
      font-size: 15px;
    }

    /* Cifras Dinámicas */
    .stats { 
      display: grid;
      grid-template-columns: repeat(auto-fit, minmax(240px, 1fr));
      gap: 24px;
      margin-top: 8px;
    }
    
    .stat { 
      background: transparent;
      border: none;
      border-left: 5px solid var(--sdg3-green);
      border-radius: 0;
      padding: 12px 0 12px 16px;
      transition: transform 0.3s ease;
      box-shadow: none;
    }
    
    .stat:hover {
      transform: translateY(-2px);
      border-left-color: var(--sdg3-dark);
    }
    
    .stat .value { 
      font-size: 42px;
      font-weight: 800;
      color: var(--sdg3-green);
      line-height: 1;
      letter-spacing: -0.02em;
      font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', sans-serif;
    }
    
    .stat .label { 
      color: var(--text-secondary);
      margin-top: 10px;
      font-size: 15px;
      font-weight: 500;
      line-height: 1.5;
    }

    /* Bloques de Imagen */
    .figure { 
      border: none;
      border-radius: 0;
      overflow: hidden;
      background: transparent;
      box-shadow: none;
    }
    
    .figure img { 
      width: 100%;
      height: auto;
      display: block;
    }
    
    .figure figcaption { 
      padding: 16px 20px;
      color: var(--text-muted);
      font-size: 14px;
      background: var(--bg-light);
      border-top: 1px solid var(--border-subtle);
    }

    /* Carrusel de Aliados */
    .carousel { 
      position: relative;
      margin-top: 8px;
    }
    
    .carousel-viewport { 
      overflow: hidden;
      border: 1px solid var(--border-light);
      border-radius: 12px;
      background: var(--bg-white);
      box-shadow: var(--shadow-sm);
    }
    
    .carousel-track { 
      display: flex;
      transition: transform 450ms cubic-bezier(0.4, 0, 0.2, 1);
    }
    
    .slide { 
      flex: 0 0 25%;
      padding: 32px;
      display: flex;
      align-items: center;
      justify-content: center;
      border-right: 1px solid var(--border-subtle);
      transition: background 0.2s ease;
    }
    
    .slide:hover { background: var(--bg-light); }
    .slide:last-child { border-right: 0; }
    
    .slide img { 
      max-height: 64px;
      width: auto;
      opacity: 0.85;
      filter: grayscale(10%);
      transition: all 0.3s ease;
    }
    
    .slide:hover img {
      opacity: 1;
      filter: grayscale(0%);
      transform: scale(1.05);
    }

    .carousel-controls { 
      display: flex;
      justify-content: center;
      gap: 12px;
      margin-top: 16px;
    }
    
    .carousel-btn { 
      appearance: none;
      border: 1px solid var(--border-light);
      background: var(--bg-white);
      padding: 10px 18px;
      border-radius: 8px;
      cursor: pointer;
      font-weight: 600;
      font-size: 14px;
      color: var(--text-secondary);
      transition: all 0.2s ease;
      box-shadow: var(--shadow-sm);
    }
    
    .carousel-btn:hover { 
      background: var(--sdg3-green);
      color: white;
      border-color: var(--sdg3-green);
      transform: translateY(-1px);
    }
    
    .carousel-btn:active { transform: translateY(0); }
    
    .dots { 
      display: flex;
      justify-content: center;
      gap: 8px;
      margin-top: 12px;
    }
    
    .dot { 
      width: 10px;
      height: 10px;
      border-radius: 50%;
      background: var(--border-light);
      transition: all 0.3s ease;
      cursor: pointer;
    }
    
    .dot:hover { background: var(--text-muted); }
    .dot.active { 
      background: var(--sdg3-green);
      transform: scale(1.2);
    }

    /* Noticias - Diseño Moderno y Minimalista */
    .news-grid { 
      display: grid; 
      grid-template-columns: repeat(auto-fit, minmax(340px, 1fr)); 
      gap: 32px; 
      margin-top: 40px;
    }
    
    .news-card {
      display: block;
      text-decoration: none;
      color: inherit;
      background: transparent;
      border: none;
      border-radius: 14px;
      overflow: hidden;
      transition: transform 0.35s cubic-bezier(0.4, 0, 0.2, 1);
      box-shadow: none;
    }
    
    .news-card:hover {
      transform: translateY(-6px);
    }
    
    .news-image {
      position: relative;
      width: 100%;
      height: 240px;
      overflow: hidden;
      background: linear-gradient(135deg, var(--bg-light) 0%, #e8eaed 100%);
    }
    
    .news-image img {
      width: 100%;
      height: 100%;
      object-fit: cover;
      display: block;
      transition: transform 0.5s cubic-bezier(0.4, 0, 0.2, 1);
    }
    
    .news-card:hover .news-image img {
      transform: scale(1.08);
    }
    
    .news-overlay {
      position: absolute;
      bottom: 0;
      left: 0;
      right: 0;
      background: linear-gradient(to top, rgba(44, 62, 80, 0.85) 0%, transparent 100%);
      padding: 20px;
      opacity: 0;
      transition: opacity 0.35s ease;
    }
    
    .news-card:hover .news-overlay {
      opacity: 1;
    }
    
    .news-badge {
      display: inline-block;
      background: var(--sdg3-green);
      color: white;
      padding: 8px 16px;
      border-radius: 24px;
      font-size: 13px;
      font-weight: 700;
      letter-spacing: 0.4px;
      box-shadow: 0 4px 12px rgba(229, 36, 59, 0.3);
      font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', sans-serif;
    }
    
    .news-content {
      padding: 28px;
    }
    
    .news-title {
      font-size: 18px;
      font-weight: 700;
      color: var(--text-primary);
      line-height: 1.4;
      margin: 0 0 14px 0;
      font-family: 'Georgia', serif;
      transition: color 0.2s ease;
    }
    
    .news-card:hover .news-title {
      color: var(--sdg3-green);
    }
    
    .news-excerpt {
      font-size: 15px;
      color: var(--text-secondary);
      line-height: 1.7;
      margin: 0;
      text-align: justify;
      hyphens: auto;
    }
    
    /* Responsive para noticias */
    @media (max-width: 1024px) {
      .news-grid {
        grid-template-columns: repeat(auto-fit, minmax(300px, 1fr));
        gap: 28px;
      }
    }
    
    @media (max-width: 768px) {
      .news-grid {
        grid-template-columns: repeat(auto-fit, minmax(280px, 1fr));
        gap: 24px;
      }
      
      .news-image {
        height: 210px;
      }
      
      .news-content {
        padding: 24px;
      }
      
      .news-title {
        font-size: 17px;
      }
      
      .news-excerpt {
        font-size: 14px;
      }
    }
    
    @media (max-width: 640px) {
      .news-grid {
        grid-template-columns: 1fr;
        gap: 20px;
        margin-top: 32px;
      }
      
      .news-image {
        height: 200px;
      }
      
      .news-content {
        padding: 20px;
      }
      
      .news-title {
        font-size: 16px;
        margin-bottom: 12px;
      }
      
      .news-excerpt {
        font-size: 14px;
      }
      
      .news-badge {
        font-size: 12px;
        padding: 6px 14px;
      }
    }

    /* Footer */
    footer { 
      border-top: none;
      padding: 40px 0 56px;
      color: var(--text-muted);
      font-size: 14px;
      background: transparent;
      text-align: center;
    }
    
    footer .container { 
      max-width: 800px;
    }

    /* Responsive Design */
    @media (max-width: 1024px) {
      .container { padding: 0 24px; }
      .grid-2 { gap: 36px; }
      .grid-3 { grid-template-columns: repeat(2, 1fr); }
      section { padding: 52px 0; }
    }
    
    @media (max-width: 768px) {
      .grid-2 { 
        grid-template-columns: 1fr;
        gap: 28px;
      }
      
      .grid-3 { 
        grid-template-columns: 1fr;
        gap: 20px;
      }
      
      .slide { flex: 0 0 33.3333%; }
      
      .hero { padding: 48px 0 36px; }
      .hero h1 { font-size: clamp(28px, 7vw, 36px); }
      .subtitle { font-size: 17px; }
      
      section { padding: 44px 0; }
      .section-title { font-size: clamp(22px, 5vw, 28px); }
      
      .card { padding: 24px; }
      .stat { padding: 20px 18px; }
      .stat .value { font-size: 36px; }
      
      .news-grid { gap: 20px; }
    }
    
    @media (max-width: 640px) {
      .container { padding: 0 20px; }
      
      .topbar-inner { padding: 12px 0; }
      .brand img { height: 38px; }
      .brand-title { display: none; }
      
      .lang-switch button { 
        padding: 7px 14px;
        font-size: 13px;
      }
      
      .slide { flex: 0 0 50%; padding: 24px 16px; }
      .slide img { max-height: 50px; }
      
      .hero { padding: 36px 0 28px; }
      .eyebrow { font-size: 11px; }
      
      section { padding: 36px 0; }
      .card { padding: 20px; }
      
      .stats { gap: 16px; }
      .stat { padding: 18px 16px; }
      .stat .value { font-size: 32px; }
      .stat .label { font-size: 14px; }
      
      .carousel-btn { 
        padding: 8px 14px;
        font-size: 13px;
      }
      
      footer { padding: 32px 0 44px; }
    }
    
    /* Print Styles */
    @media print {
      .topbar { position: static; }
      .lang-switch { display: none; }
      .carousel-controls { display: none; }
      .dots { display: none; }
      section { page-break-inside: avoid; }
    }

    /* Utilidad bilingüe */
    [data-lang-content] { display: none; }
    [data-lang-content][data-visible="true"] { display: block; }

    /* Intro overlay */
    #intro-overlay {
      position: fixed;
      inset: 0;
      z-index: 10000;
      /* Fondo con degradado suave más elegante */
      background: linear-gradient(135deg, #3a7a2b 0%, #4C9F38 50%, #8bc34a 100%);
      display: grid;
      place-items: center;
      color: #ffffff;
    }
    #intro-overlay .intro-inner { 
      text-align: center; 
      animation: introText 700ms cubic-bezier(0.2, 0.8, 0.2, 1) both; 
      /* Sin glassmorphism - solo contenedor limpio */
      padding: 20px 24px;
    }
    #intro-overlay .intro-logo {
      display: block;
      width: clamp(120px, 18vw, 200px);
      height: auto;
      margin: 0 auto 14px auto;
      background: rgba(255,255,255,0.92);
      border-radius: 14px;
      padding: 10px;
      border: 1px solid rgba(0,0,0,0.04);
      box-shadow: 0 10px 24px rgba(0,0,0,0.15);
      animation: introLogo 700ms cubic-bezier(0.2, 0.8, 0.2, 1) both 40ms;
    }
    #intro-overlay .intro-mark {
      font-weight: 800;
      letter-spacing: 0.08em;
      font-size: clamp(36px, 7vw, 72px);
      line-height: 1.1;
    }
    #intro-overlay .intro-sub {
      margin-top: 8px;
      font-weight: 700;
      font-size: clamp(18px, 3.5vw, 28px);
      opacity: 0.95;
      letter-spacing: 0.06em;
    }
    #intro-overlay.hide { 
      animation: introOut 650ms cubic-bezier(0.4, 0, 0.2, 1) forwards; 
    }
    @keyframes introText {
      from { opacity: 0; transform: translateY(8px) scale(0.985); }
      to { opacity: 1; transform: translateY(0) scale(1); }
    }
    @keyframes introOut {
      to { opacity: 0; transform: translateY(-12%); }
    }
    @keyframes introLogo {
      from { opacity: 0; transform: translateY(8px) scale(0.96); }
      to { opacity: 1; transform: translateY(0) scale(1); }
    }
    @keyframes dropIn {
      from { opacity: 0; transform: translateY(14px); }
      to { opacity: 1; transform: none; }
    }
    body.intro-playing { overflow: hidden; }
    body.intro-playing .lang-switch { opacity: 0; pointer-events: none; }
    body.intro-playing .hero,
    body.intro-playing main,
    body.intro-playing footer { opacity: 0; transform: translateY(12px); }
    body.intro-done .hero { animation: dropIn 600ms cubic-bezier(0.2, 0.8, 0.2, 1) both 50ms; }
    body.intro-done main { animation: dropIn 650ms cubic-bezier(0.2, 0.8, 0.2, 1) both 100ms; }
    body.intro-done footer { animation: dropIn 700ms cubic-bezier(0.2, 0.8, 0.2, 1) both 180ms; }

    @media (prefers-reduced-motion: reduce) {
      #intro-overlay { display: none !important; }
      body.intro-playing .hero,
      body.intro-playing main,
      body.intro-playing footer { opacity: 1; transform: none; }
      body.intro-done .hero,
      body.intro-done main,
      body.intro-done footer { animation: none; }
    }

  </style>
</head>
