    <!-- ODS 5 -->
    <a href="ods5_informe.html" class="sdg-nav-item sdg-5" data-sdg="5">
      <div class="sdg-card">
        <img src="https://sdgbook.com/wp-content/uploads/sites/2/2019/09/5.png" alt="ODS 5" class="sdg-card-image" onerror="this.src='https://placehold.co/240x180/FF3A21/ffffff?text=ODS+5'">
