values (4, 2025, 'sdgudes.github.io', $ods_json${"ods":4,"edicion":2025,"fuente":"sdgudes.github.io","archivo":"ods4_informe.html","titulo":{"es":"ODS 4: Educación de Calidad","en":"SDG 4: Quality Education"},"tesis":[{"es":"El Objetivo de Desarrollo Sostenible 4 (ODS 4): Educación de Calidad busca \"garantizar una educación inclusiva, equitativa y de calidad y promover oportunidades de aprendizaje durante toda la vida para todos\". Este objetivo es la piedra angular para el desarrollo sostenible, la erradicación de la pobreza y la mejora de la calidad de vida.","en":"Sustainable Development Goal 4 (SDG 4): Quality Education seeks to \"ensure inclusive, equitable and quality education and promote lifelong learning opportunities for all.\" This goal is the cornerstone for sustainable development, poverty eradication and improving quality of life."}],"cifras":[{"v":"4,849","etiqueta":{"es":"Graduados Totales","en":"Total Graduates"},"nota":{"es":"La UDES es una máquina de talento. Del total de 4,849 graduados, una parte esencial está dedicada a transformar la educación del país.","en":"UDES is a talent machine. Of the total 4,849 graduates, an essential part is dedicated to transforming the country's education."}},{"v":"974","etiqueta":{"es":"Nuevos Maestros","en":"New Teachers"},"nota":{"es":"¡974 de nuestros egresados obtuvieron una titulación que los faculta para la enseñanza primaria! Estamos formando a la base de la educación nacional con los más altos estándares de calidad.","en":"974 of our graduates obtained a degree that qualifies them for primary teaching! We are training the foundation of national education with the highest quality standards."}},{"v":"20.09%","etiqueta":{"es":"Proporción Docente","en":"Teaching Proportion"},"nota":{"es":"20.09% de nuestros graduados están calificados para la docencia (≈0.2009). Esto subraya el compromiso de la UDES de aportar educadores competentes que garantizan el futuro de la educación de calidad en Colombia.","en":"20.09% of our graduates are qualified for teaching (≈0.2009). This underscores UDES's commitment to providing competent educators who guarantee the future of quality education in Colombia."}},{"v":"16,030","etiqueta":{"es":"Personas beneficiadas","en":"People benefited"},"nota":{"es":"por programas de Proyección Social (Multicampus).","en":"by social outreach programs (multicampus)."}},{"v":"3,220","etiqueta":{"es":"Estudiantes UDES","en":"UDES students"},"nota":{"es":"participando en Proyección Social.","en":"participating in social outreach programs."}},{"v":"3,213","etiqueta":{"es":"Pacientes beneficiados","en":"Patients benefited"},"nota":{"es":"por Programa EIP (urbanos y rurales).","en":"by the IPE Program (urban & rural)."}},{"v":"680","etiqueta":{"es":"Estudiantes EIP","en":"IPE students"},"nota":{"es":"vinculados al programa EIP.","en":"linked to the IPE program."}},{"v":"585","etiqueta":{"es":"Familias intervenidas","en":"Families reached"},"nota":{"es":"por el Programa MIUDES.","en":"by the MIUDES Program."}},{"v":"502","etiqueta":{"es":"Estudiantes MIUDES","en":"MIUDES students"},"nota":{"es":"vinculados al Programa MIUDES.","en":"linked to the MIUDES Program."}},{"v":"593","etiqueta":{"es":"Consultorio Jurídico","en":"Legal Clinic"},"nota":{"es":"usuarios atendidos (2024A).","en":"users served (2024A)."}},{"v":"2,072","etiqueta":{"es":"Asuntos Migratorios","en":"Migration support"},"nota":{"es":"personas apoyadas.","en":"people supported."}},{"v":"170","etiqueta":{"es":"Beneficiarios discapacidad","en":"Disability beneficiaries"},"nota":{"es":"programas de atención a la discapacidad.","en":"beneficiaries of disability support programs."}},{"v":"150","etiqueta":{"es":"Orientación vocacional","en":"Vocational guidance"},"nota":{"es":"jóvenes de bachillerato (Proyecto Maquilando Felicidad).","en":"high-school youth (Maquilando Felicidad project)."}},{"v":"15","etiqueta":{"es":"Semilleros de Experiencia","en":"Experience seedbeds"},"nota":{"es":"activos para estudiantes de bachillerato.","en":"active for high-school students."}},{"v":"1,287","etiqueta":{"es":"Nuevos Estudiantes","en":"New Students"},"nota":{"es":"La UDES es una plataforma de movilidad social. 1,287 nuevos estudiantes iniciaron su carrera, enfocándonos en dar acceso a quienes más lo necesitan, transformando historias a través de la educación.","en":"UDES is a social mobility platform. 1,287 new students started their careers, focusing on providing access to those who need it most, transforming lives through education."}},{"v":"308","etiqueta":{"es":"Primera Generación","en":"First Generation"},"nota":{"es":"De los 1,287 nuevos estudiantes, 308 son estudiantes de primera generación. Son los pioneros en sus familias en acceder a la educación superior. ¡Estamos rompiendo barreras!","en":"Of the 1,287 new students, 308 are first-generation students. They are the pioneers in their families to access higher education. We are breaking barriers!"}},{"v":"23.93%","etiqueta":{"es":"Proporción de Inclusión","en":"Inclusion Proportion"},"nota":{"es":"Un impresionante 23.93% de nuestros nuevos estudiantes son de primera generación (≈0.2393). Esto reafirma nuestro rol como agentes de equidad social, brindando una educación de calidad que cambia vidas y familias.","en":"An impressive 23.93% of our new students are first-generation (≈0.2393). This reaffirms our role as agents of social equity, providing quality education that changes lives and families."}},{"v":"16,030","etiqueta":{"es":"Beneficiarios en la Comunidad","en":"Community Beneficiaries"},"nota":{"es":"Personas que han recibido algún servicio, taller o intervención de El Aula Viva.","en":"People who have received a service, workshop or intervention from El Aula Viva."}},{"v":"3,220","etiqueta":{"es":"Estudiantes en Formación","en":"UDES Students Trained"},"nota":{"es":"Participantes universitarios que fueron capacitados o involucrados en las actividades de aula y campo.","en":"University participants who were trained or involved in classroom and field activities."}},{"v":"20","etiqueta":{"es":"Programas MIUDES","en":"MIUDES Programs"},"nota":{"es":"Programas académicos articulados con la estrategia (20 programas).","en":"Academic programs articulated with the strategy (20 programs)."}},{"v":"502","etiqueta":{"es":"Estudiantes MIUDES","en":"MIUDES Students"},"nota":{"es":"Estudiantes participantes vinculados al programa MIUDES (502).","en":"Student participants linked to the MIUDES program (502)."}},{"v":"585","etiqueta":{"es":"Familias Intervenidas","en":"Families Reached"},"nota":{"es":"Familias que recibieron intervenciones o acompañamiento (585).","en":"Families who received interventions or support (585)."}},{"v":"593","etiqueta":{"es":"Consultorio Jurídico (2024A)","en":"Legal Clinic (2024A)"},"nota":{"es":"Usuarios atendidos en el Consultorio Jurídico durante el primer periodo 2024.","en":"Users served by the Legal Clinic during the first term of 2024."}},{"v":"2,072","etiqueta":{"es":"Asuntos Migratorios","en":"Migration Support"},"nota":{"es":"Personas apoyadas por iniciativas relacionadas con movilidad y atención a población migrante.","en":"People supported by initiatives related to mobility and assistance to migrant populations."}},{"v":"150","etiqueta":{"es":"Orientación Vocacional","en":"Vocational Guidance"},"nota":{"es":"Jóvenes orientados en procesos de transferencia de habilidades (ODS 4.4).","en":"Young people guided in skills transfer processes (SDG 4.4)."}},{"v":"25","etiqueta":{"es":"Capacitación Técnica","en":"Technical Training"},"nota":{"es":"Jóvenes y mujeres que recibieron capacitación técnica especializada (25).","en":"Young people and women who received specialized technical training (25)."}},{"v":"9","etiqueta":{"es":"Grupos de Investigación","en":"Research Groups"},"nota":{"es":"","en":""}},{"v":"2","etiqueta":{"es":"Productos","en":"Products"},"nota":{"es":"","en":""}},{"v":"104","etiqueta":{"es":"Proyectos","en":"Projects"},"nota":{"es":"","en":""}},{"v":"36","etiqueta":{"es":"Semilleros de Investigación","en":"Research Seedbeds"},"nota":{"es":"","en":""}}],"cifras_no_importadas":[],"videos":[],"enlaces":[{"href":"https://udes.edu.co/images/micrositios/biblioteca/reglamento-biblioteca-udes.pdf","texto":{"es":"Reglamento Biblioteca","en":"Reglamento Biblioteca"},"clase":"btn-link","imagen":"","sin_traduccion":true},{"href":"https://es-la.facebook.com/Bibliotecaudesbucaramanga/","texto":{"es":"Facebook Biblioteca UDES","en":"Facebook Biblioteca UDES"},"clase":"btn-link secondary","imagen":"","sin_traduccion":true},{"href":"https://aulaextendida.udes.edu.co/login/index.php","texto":{"es":"Aula Extendida","en":"Aula Extendida"},"clase":"btn-link","imagen":"","sin_traduccion":true},{"href":"https://udes.edu.co/educacion-continua/portafolio/programas-de-formacion-para-toda-la-vida","texto":{"es":"Portafolio Educación Continua","en":"Portafolio Educación Continua"},"clase":"btn-link secondary","imagen":"","sin_traduccion":true},{"href":"https://udes.edu.co/estudia/educacion-continua","texto":{"es":"Cursos Educación Continua","en":"Cursos Educación Continua"},"clase":"btn-link","imagen":"","sin_traduccion":true},{"href":"https://vlib.unired.edu.co/opac/#indice","texto":{"es":"UNIRED (OPAC)","en":"UNIRED (OPAC)"},"clase":"btn-link secondary","imagen":"","sin_traduccion":true},{"href":"https://udes.edu.co/images/micrositios/extension/informe-gestion-vicext-2024-2.pdf","texto":{"es":"Ver detalles de Proyección Social","en":"Ver detalles de Proyección Social"},"clase":"btn-link","imagen":"","sin_traduccion":true},{"href":"https://sigiip.udes.edu.co/?returnUrl=%2F","texto":{"es":"Conoce todas nuestras cifras de investigación","en":"Explore all our research data"},"clase":"","imagen":""},{"href":"https://udes.edu.co/ensenanza/noticias/estudiantes-de-la-facultad-de-ciencias-medicas-y-de-la-salud-udes-realizaron-su-ii-practica-de-educacion-interprofesional","texto":{"es":"Estudiantes de la Facultad de Ciencias Médica