  <script>
    (function(){
      const esBtn = document.querySelector('[data-lang-btn="es"]');
      const enBtn = document.querySelector('[data-lang-btn="en"]');
      const translatable = document.querySelectorAll('[data-lang-content]');

      function setLang(lang){
        document.documentElement.setAttribute('lang', lang);
        translatable.forEach(node => {
          const visible = node.getAttribute('data-lang') === lang;
          node.setAttribute('data-visible', visible ? 'true' : 'false');
          node.style.display = visible ? '' : 'none';
        });
        esBtn.classList.toggle('active', lang === 'es');
        enBtn.classList.toggle('active', lang === 'en');
        esBtn.setAttribute('aria-pressed', String(lang === 'es'));
        enBtn.setAttribute('aria-pressed', String(lang === 'en'));
        try { localStorage.setItem('ods-lang', lang); } catch(e) {}
      }

      const storedLang = (function(){
        try { return localStorage.getItem('ods-lang') || 'es'; } catch(e) { return 'es'; }
      })();
      setLang(storedLang);
      esBtn.addEventListener('click', () => setLang('es'));
      enBtn.addEventListener('click', () => setLang('en'));

      // Auto-activar el ODS actual según el nombre del archivo
      const m = location.pathname.match(/ods(\d+)_informe\.html$/i);
      if (m && m[1]){
        const current = m[1];
        const activeEl = document.querySelector(`.sdg-navbar .sdg-nav-item[data-sdg="${current}"]`);
        if (activeEl) activeEl.classList.add('active');
      }
    })();
  </script>
</body>
</html>
$ods_html$)
on conflict (ods, edition, source) do update
   set parsed = excluded.parsed, raw_html = excluded.raw_html, imported_at = now()
 where public.ods_report_archive.parsed is distinct from excluded.parsed
    or public.ods_report_archive.raw_html is distinct from excluded.raw_html;

