            <a class="card" href="https://udes.edu.co/extension/noticias/enfermeria-udes-celebro-el-dia-internacional-de-la-mujer-con-cuidadores-de-personas-en-situacion-de-cronicidad-en-bucaramanga" target="_blank" rel="noopener noreferrer">
              <img src="https://udes.edu.co/media/k2/items/cache/19a14b5e65677e11c2277fac821d2141_XL.jpg" alt="Cuidadores - Enfermería UDES" onerror="this.onerror=null;this.src='https://placehold.co/480x320/FF3A21/ffffff?text=Cuidadores'" style="width:100%; height:160px; object-fit:cover; border-radius:10px; margin-bottom:12px;" />
              <div style="font-weight:700; color:var(--text-primary);">Enfermería UDES celebró el Día Internacional de la Mujer con cuidadores de personas en situación de cronicidad en Bucaramanga</div>
            </a>

            <a class="card" href="https://udes.edu.co/institucional/noticias/udes-implementa-recursos-para-la-inclusion-y-la-excelencia-academica" target="_blank" rel="noopener noreferrer">
              <img src="https://placehold.co/480x320/FF3A21/ffffff?text=Inclusi%C3%B3n" alt="UDES implementa recursos para la inclusión" onerror="this.onerror=null;this.src='https://placehold.co/480x320/FF3A21/ffffff?text=No+image'" style="width:100%; height:160px; object-fit:cover; border-radius:10px; margin-bottom:12px;" />
              <div style="font-weight:700; color:var(--text-primary);">UDES implementa recursos para la inclusión y la excelencia académica</div>
            </a>
          </div>
        </div>
      </section>
    </main>
  <footer role="contentinfo"><div class="container"><div data-lang-content data-lang="es">© 2025 · Informe ODS 5 · Versión para uso académico.</div><div data-lang-content data-lang="en">© 2025 · SDG 5 Report · Academic use version.</div></div></footer>
  <script>
    (function(){
      const esBtn = document.querySelector('[data-lang-btn="es"]');
      const enBtn = document.querySelector('[data-lang-btn="en"]');
      const translatable = document.querySelectorAll('[data-lang-content]');

      function setLang(lang){
        document.documentElement.setAttribute('lang', lang);
        translatable.forEach(node => {
          const visible = node.getAttribute('data-lang') === lang;
          node.setAttribute('data-visible', visible ? 'true' : 'false');
          node.style.display = visible ? '' : 'none';
        });
        esBtn.classList.toggle('active', lang === 'es');
        enBtn.classList.toggle('active', lang === 'en');
        esBtn.setAttribute('aria-pressed', String(lang === 'es'));
        enBtn.setAttribute('aria-pressed', String(lang === 'en'));
        try { localStorage.setItem('ods-lang', lang); } catch(e) {}
      }

      const storedLang = (function(){
        try { return localStorage.getItem('ods-lang') || 'es'; } catch(e) { return 'es'; }
      })();
      setLang(storedLang);
      esBtn.addEventListener('click', () => setLang('es'));
      enBtn.addEventListener('click', () => setLang('en'));

      // Auto-activar el ODS actual según el nombre del archivo
      const m = location.pathname.match(/ods(\d+)_informe\.html$/i);
      if (m && m[1]){
        const current = m[1];
        const activeEl = document.querySelector(`.sdg-navbar .sdg-nav-item[data-sdg="${current}"]`);
        if (activeEl) activeEl.classList.add('active');
      }
    })();
  </script>
</body>
</html>
