on conflict (ods, edition, source) do update
   set parsed = excluded.parsed, raw_html = excluded.raw_html, imported_at = now()
 where public.ods_report_archive.parsed is distinct from excluded.parsed
    or public.ods_report_archive.raw_html is distinct from excluded.raw_html;

insert into public.ods_report_archive (ods, edition, source, parsed, raw_html)
values (6, 2025, 'sdgudes.github.io', $ods_json${"ods":6,"edicion":2025,"fuente":"sdgudes.github.io","archivo":"ods6_informe.html","titulo":{"es":"ODS 6: Agua limpia y saneamiento","en":"SDG 6: Clean Water and Sanitation"},"tesis":[{"es":"La Universidad de Santander (UDES) articula su misión educativa y de investigación con un profundo compromiso con la Agenda 2030. Más allá de la academia, la UDES actúa como un agente de cambio tangible, generando soluciones eficientes que conectan las necesidades del territorio con los Objetivos de Desarrollo Sostenible (ODS). Este informe evidencia, a través de acciones estratégicas recientes, cómo nuestra institución integra el humanismo y la innovación para la preservación del capital natural y el bienestar social, enfocándose primordialmente en los ODS 6 (Agua Limpia y Saneamiento), ODS 7 (Energía Asequible y No Contaminante), ODS 9 (Industria, Innovación e Infraestructura) y ODS 13 (Acción por el Clima).","en":"The University of Santander (UDES) aligns its educational and research mission with a deep commitment to the 2030 Agenda. Beyond academia, UDES acts as a tangible agent of change, generating efficient solutions that connect territorial needs with the Sustainable Development Goals (SDGs). This report demonstrates, through recent strategic actions, how our institution integrates humanism and innovation for the preservation of natural capital and social wellbeing, focusing primarily on SDG 6 (Clean Water and Sanitation), SDG 7 (Affordable and Clean Energy), SDG 9 (Industry, Innovation and Infrastructure) and SDG 13 (Climate Action)."}],"cifras":[],"cifras_no_importadas":[],"videos":[],"enlaces":[],"imagenes":[{"src":"https://sdgbook.com/wp-content/uploads/sites/2/2019/09/6.png","alt":{"es":"Logo ODS 6","en":"Logo ODS 6"},"pie":{"es":"","en":""},"tipo":"ilustracion-ods","zona":"portada"}],"fotos_udes":[],"graficos":[],"secciones":[{"titulo":{"es":"","en":""},"piezas":[{"t":"imagen","zona":"portada","src":"https://sdgbook.com/wp-content/uploads/sites/2/2019/09/6.png","alt":{"es":"Logo ODS 6","en":"Logo ODS 6"},"pie":{"es":"","en":""},"tipo":"ilustracion-ods"},{"t":"parrafo","zona":"cuerpo","texto":{"es":"La Universidad de Santander (UDES) articula su misión educativa y de investigación con un profundo compromiso con la Agenda 2030. Más allá de la academia, la UDES actúa como un agente de cambio tangible, generando soluciones eficientes que conectan las necesidades del territorio con los Objetivos de Desarrollo Sostenible (ODS). Este informe evidencia, a través de acciones estratégicas recientes, cómo nuestra institución integra el humanismo y la innovación para la preservación del capital natural y el bienestar social, enfocándose primordialmente en los ODS 6 (Agua Limpia y Saneamiento), ODS 7 (Energía Asequible y No Contaminante), ODS 9 (Industria, Innovación e Infraestructura) y ODS 13 (Acción por el Clima).","en":"The University of Santander (UDES) aligns its educational and research mission with a deep commitment to the 2030 Agenda. Beyond academia, UDES acts as a tangible agent of change, generating efficient solutions that connect territorial needs with the Sustainable Development Goals (SDGs). This report demonstrates, through recent strategic actions, how our institution integrates humanism and innovation for the preservation of natural capital and social wellbeing, focusing primarily on SDG 6 (Clean Water and Sanitation), SDG 7 (Affordable and Clean Energy), SDG 9 (Industry, Innovation and Infrastructure) and SDG 13 (Climate Action)."}}]},{"titulo":{"es":"Innovación para la Transición Energética y Acción Climática (ODS 7 y ODS 13)","en":"Innovation for the Energy Transition and Climate Action (SDG 7 & SDG 13)"},"piezas":[{"t":"parrafo","zona":"cuerpo","texto":{"es":"El humanismo en la UDES se traduce en buscar soluciones que mejoren la calidad de vida de las personas, especialmente de las más vulnerables, mientras se protege el planeta. La innovadora estufa de hidrógeno desarrollada en la UDES es el ejemplo paradigmático de esta filosofía.","en":"Humanism at UDES translates into seeking solutions that improve people's quality of life, especially the most vulnerable, while protecting the planet. the innovative hydrogen stove developed at UDES is the paradigmatic example of this philosophy."}},{"t":"titulo","zona":"cuerpo","nivel":4,"texto":{"es":"Humanismo y Eficiencia Energética","en":"Humanism and Energy Efficiency"}},{"t":"parrafo","zona":"cuerpo","texto":{"es":"Presentada y validada en el escenario global de la COP16 (Noticia: Estufa de hidrógeno [...] pasa la prueba en la COP16), esta tecnología representa una revolución en la eficiencia (ODS 7 y ODS 9). La capacidad de cocinar para una familia de cinco miembros durante tres meses, utilizando únicamente un galón de agua, no es solo un hito científico; es una herramienta de equidad social y acción climática.","en":"Presented and validated on the global stage of COP16 (News: Hydrogen stove [...] tested at COP16), this technology represents a revolution in efficiency (SDG 7 and SDG 9). The ability to cook for a family of five for three months using only one gallon of water is not just a scientific milestone; it is a tool for social equity and climate action."}},{"t":"titulo","zona":"cuerpo","nivel":4,"texto":{"es":"Conexión Global","en":"Global Connection"}},{"t":"parrafo","zona":"cuerpo","texto":{"es":"El reconocimiento de esta innovación por parte del Ministerio de Minas y Energía en un evento de la talla de la COP16 valida la capacidad de la UDES para generar soluciones escalables que responden a la crisis climática global. Estamos creando tecnología limpia que reduce la deforestación (al reemplazar la leña) y ofrece autonomía energética, conectando nuestro ingenio local con los desafíos globales más apremiantes (ODS 13).","en":"The recognition of this innovation by the Ministry of Mines and Energy at an event such as COP16 validates UDES's ability to generate scalable solutions that respond to the global climate crisis. We are creating clean technology that reduces deforestation (by replacing firewood) and offers energy autonomy, connecting our local ingenuity with the most pressing global challenges (SDG 13)."}},{"t":"titulo","zona":"cuerpo","nivel":3,"texto":{"es":"El Agua como Eje de Vida y Sostenibilidad (ODS 6)","en":"Water as an Axis of Life and Sustainability (SDG 6)"}},{"t":"parrafo","zona":"cuerpo","texto":{"es":"En un contexto nacional marcado por desafíos hídricos, como la sequía que atraviesa Colombia, la UDES reafirma su liderazgo en sostenibilidad ambiental (Noticia: Día de la Tierra). Entendemos que la gestión del agua no es solo una responsabilidad técnica, sino un imperativo humano. Nuestra estrategia no se limita a la concienciación; se traduce en acción directa y eficiente sobre las fuentes hídricas de la región.","en":"In a national context marked by water challenges, such as the drought affecting Colombia, UDES reaffirms its leadership in environmental sustainability (News: Earth Day). We understand that water management is not only a technical responsibility but a human imperative. Our strategy goes beyond awareness; it translates into direct and efficient action on the region's water sources."}},{"t":"titulo","zona":"cuerpo","nivel":4,"texto":{"es":"Eficiencia Tecnológica para el Saneamiento","en":"Technological Efficiency for Sanitation"}},{"t":"parrafo","zona":"cuerpo","texto":{"es":"La UDES se ha consolidado como un aliado estratégico en la recuperación de cuencas vitales. Prueba de ello es nuestra contribución al desarrollo de una tecnología innovadora para la desinfección de aguas residuales en el río Fonce, en San Gil (Noticia: UDES contribuye [...] río Fonce). Este proyecto (alineado con ODS 6 y ODS 9) no solo representa un avance en cavitación hidrodinámica, sino que es una muestra de eficiencia aplicada: es la ciencia de la UDES garantizando la sostenibilidad de un recurso vital para miles de personas.","en":"UDES has established itself as a strategic ally in the recovery of vital watersheds. Proof of this is our contribution to the development of an innovative technology for disinfecting wastewater in the Fonce River, in San Gil (News: UDES contributes [...] Fonce River). This project (aligned with SDG 6 and SDG 9) not only represents an advancement in hydrodynamic cavitation, but is an example of applied efficiency: UDES science ensuring the sustainability of a vital resource for thousands of people."}},{"t":"titulo","zona":"cuerpo","nivel":4,"texto":{"es":"Conexión Territorial y Diagnóstico Preciso","en":"Territorial Connection and Precise Diagnosis"}},{"t":"parrafo","zona":"cuerpo","texto":{"es":"Nuestra conexión con las comunidades se materializa en el territorio. En una alianza estratégica con la Universidad Popular del César (UPC), (Noticia: UDES y UPC diagnostican [...] Caño El Pital), estamos realizando un diagnóstico crucial sobre la calidad del agua en el Caño El Pital, en el Bosque Natural de Agüil (Cesar). Este proyecto integrador (ODS 6 y ODS 15) demuestra nuestro compromiso de ir a la fuente de los problemas, colaborando (ODS 17) para proteger ecosistemas frágiles y asegurar que el desarrollo no comprometa la salud ambiental de la región.","en":"Our connection with communities materializes in the field. In a strategic alliance with the Universidad Popular del César (UPC) (News: UDES and UPC diagnose [...] Caño El Pital), we are carrying out a crucial diagnosis of water quality at Caño El Pital, in the Agüil Natural Forest (Cesar). This integrative project (SDG 6 and SDG 15) demonstrates our commitment to go to the source of problems, collaborating (SDG 17) to protect fragile ecosystems and ensure that development does not compromise the region's environmental health."}}]},{"titulo":{"es":"Una Narrativa de Impacto Coherente","en":"A Coherent Impact Narrative"},"piezas":[{"t":"parrafo","zona":"cuerpo","texto":{"es":"Las acciones de la Universidad de Santander no son esfuerzos aislados. Configuran una narrativa coherente de impacto que vincula la protección de nuestros recursos naturales (Día de la Tierra) con la provisión de soluciones tecnológicas de vanguardia (Estufa de Hidrógeno).","en":"The actions of the University of Santander are not isolated efforts. They form a coherent impact narrative that links the protection of our natural resources (Earth Day) with the provision of cutting-edge technological solutions (Hydrogen Stove)."}},{"t":"parrafo","zona":"cuerpo","texto":{"es":"Eficiencia: Pasamos del diagnóstico (Caño El Pital) a la solución aplicada (Río Fonce).","en":"Efficiency: We move from diagnosis (Caño El Pital) to applied solution (Río Fonce)."}},{"t":"parrafo","zona":"cuerpo","texto":{"es":"Conexión: Creamos puentes entre instituciones (UPC), el gobierno (Ministerio de Minas) y escenarios globales (COP16).","en":"Connection: We build bridges between institutions (UPC), government (Ministry of Mines) and global forums (COP16)."}},{"t":"parrafo","zona":"cuerpo","texto":{"es":"Humanismo: Ponemos la ciencia al servicio de las necesidades básicas (agua limpia, energía para cocinar) de las comunidades.","en":"Humanism: We put science at the service of communities' basic needs (clean water, energy for cooking)."}},{"t":"parrafo","zona":"cuerpo","texto":{"es":"La UDES demuestra con hechos su compromiso con los ODS, integrando la sostenibilidad en su ADN y probando que es posible generar un impacto positivo, medible y profundamente humano.","en":"UDES demonstrates through action its commitment to the SDGs, embedding sustainability in its DNA and proving that it is possible to generate positive, measurable and deeply human impact."}}]}],"bloques":[{"sec":"tesis","text":"La Universidad de Santander (UDES) articula su misión educativa y de investigación con un profundo compromiso con la Agenda 2030. Más allá de la academia, la UDES actúa como un agente de cambio tangible, generando soluciones eficientes que conectan las necesidades del territorio con los Objetivos de Desarrollo Sostenible (ODS). Este informe evidencia, a través de acciones estratégicas recientes, cómo nuestra institución integra el humanismo y la innovación para la preservación del capital natural y el bienestar social, enfocándose primordialmente en los ODS 6 (Agua Limpia y Saneamiento), ODS 7 (Energía Asequible y No Contaminante), ODS 9 (Industria, Innovación e Infraestructura) y ODS 13 (Acción por el Clima).","text_en":"The University of Santander (UDES) aligns its educational and research mission with a deep commitment to the 2030 Agenda. Beyond academia, UDES acts as a tangible agent of change, generating efficient solutions that connect territorial needs with the Sustainable Development Goals (SDGs). This report demonstrates, through recent strategic actions, how our institution integrates humanism and innovation for the preservation of natural capital and social wellbeing, focusing primarily on SDG 6 (Clean Water and Sanitation), SDG 7 (Affordable and Clean Energy), SDG 9 (Industry, Innovation and Infrastructure) and SDG 13 (Climate Action).","pos":1,"enabled":true,"warn":null},{"sec":"hicimos","text":"Innovación para la Transición Energética y Acción Climática (ODS 7 y ODS 13). El humanismo en la UDES se traduce en buscar soluciones que mejoren la calidad de vida de las personas, especialmente de las más vulnerables, mientras se protege el planeta. La innovadora estufa de hidrógeno desarrollada en la UDES es el ejemplo paradigmático de esta filosofía.","text_en":"Innovation for the Energy Transition and Climate Action (SDG 7 & SDG 13). Humanism at UDES translates into seeking solutions that improve people's quality of life, especially the most vulnerable, while protecting the planet. the innovative hydrogen stove developed at UDES is the paradigmatic example of this philosophy.","encabezado":"Innovación para la Transición Energética y Acción Climática (ODS 7 y ODS 13)","pos":2,"enabled":true,"warn":null},{"sec":"hicimos","text":"Humanismo y Eficiencia Energética. Presentada y validada en el escenario global de la COP16 (Noticia: Estufa de hidrógeno [...] pasa la prueba en la COP16), esta tecnología representa una revolución en la eficiencia (ODS 7 y ODS 9). La capacidad de cocinar para una familia de cinco miembros durante tres meses, utilizando únicamente un galón de agua, no es solo un hito científico; es una herramienta de equidad social y acción climática.","text_en":"Humanism and Energy Efficiency. Presented and validated on the global stage of COP16 (News: Hydrogen stove [...] tested at COP16), this technology represents a revolution in efficiency (SDG 7 and SDG 9). The ability to cook for a family of five for three months using only one gallon of water is not just a scientific milestone; it is a tool for social equity and climate action.","encabezado":"Humanismo y Eficiencia Energética","pos":3,"enabled":true,"warn":null},{"sec":"hicimos","text":"Conexión Global. El reconocimiento de esta innovación por parte del Ministerio de Minas y Energía en un evento de la talla de la COP16 valida la capacidad de la UDES para generar soluciones escalables que responden a la crisis climática global. Estamos creando tecnología limpia que reduce la deforestación (al reemplazar la leña) y ofrece autonomía energética, conectando nuestro ingenio local con los desafíos globales más apremiantes (ODS 13).","text_en":"Global Connection. The recognition of this innovation by the Ministry of Mines and Energy at an event such as COP16 validates UDES's ability to generate scalable solutions that respond to the global climate crisis. We are creating clean technology that reduces deforestation (by replacing firewood) and offers energy autonomy, connecting our local ingenuity with the most pressing global challenges (SDG 13).","encabezado":"Conexión Global","pos":4,"enabled":true,"warn":null},{"sec":"hicimos","text":"El Agua como Eje de Vida y Sostenibilidad (ODS 6). En un contexto nacional marcado por desafíos hídricos, como la sequía que atraviesa Colombia, la UDES reafirma su liderazgo en sostenibilidad ambiental (Noticia: Día de la Tierra). Entendemos que la gestión del agua no es solo una responsabilidad técnica, sino un imperativo humano. Nuestra estrategia no se limita a la concienciación; se traduce en acción directa y eficiente sobre las fuentes hídricas de la región.","text_en":"Water as an Axis of Life and Sustainability (SDG 6). In a national context marked by water challenges, such as the drought affecting Colombia, UDES reaffirms its leadership in environmental sustainability (News: Earth Day). We understand that water management is not only a technical responsibility but a human imperative. Our strategy goes beyond awareness; it translates into direct and efficient action on the region's water sources.","encabezado":"El Agua como Eje de Vida y Sostenibilidad (ODS 6)","pos":5,"enabled":true,"warn":null},{"sec":"hicimos","text":"Eficiencia Tecnológica para el Saneamiento. La UDES se ha consolidado como un aliado estratégico en la recuperación de cuencas vitales. Prueba de ello es nuestra contribución al desarrollo de una tecnología innovadora para la desinfección de aguas residuales en el río Fonce, en San Gil (Noticia: UDES contribuye [...] río Fonce). Este proyecto (alineado con ODS 6 y ODS 9) no solo representa un avance en cavitación hidrodinámica, sino que es una muestra de eficiencia aplicada: es la ciencia de la UDES garantizando la sostenibilidad de un recurso vital para miles de personas.","text_en":"Technological Efficiency for Sanitation. UDES has established itself as a strategic ally in the recovery of vital watersheds. Proof of this is our contribution to the development of an innovative technology for disinfecting wastewater in the Fonce River, in San Gil (News: UDES contributes [...] Fonce River). This project (aligned with SDG 6 and SDG 9) not only represents an advancement in hydrodynamic cavitation, but is an example of applied efficiency: UDES science ensuring the sustainability of a vital resource for thousands of people.","encabezado":"Eficiencia Tecnológica para el Saneamiento","pos":6,"enabled":true,"warn":null},{"sec":"hicimos","text":"Conexión Territorial y Diagnóstico Preciso. Nuestra conexión con las comunidades se materializa en el territorio. En una alianza estratégica con la Universidad Popular del César (UPC), (Noticia: UDES y UPC diagnostican [...] Caño El Pital), estamos realizando un diagnóstico crucial sobre la calidad del agua en el Caño El Pital, en el Bosque Natural de Agüil (Cesar). Este proyecto integrador (ODS 6 y ODS 15) demuestra nuestro compromiso de ir a la fuente de los problemas, colaborando (ODS 17) para proteger ecosistemas frágiles y asegurar que el desarrollo no comprometa la salud ambiental de la región.","text_en":"Territorial Connection and Precise Diagnosis. Our connection with communities materializes in the field. In a strategic alliance with the Universidad Popular del César (UPC) (News: UDES and UPC diagnose [...] Caño El Pital), we are carrying out a crucial diagnosis of water quality at Caño El Pital, in the Agüil Natural Forest (Cesar). This integrative project (SDG 6 and SDG 15) demonstrates our commitment to go to the source of problems, collaborating (SDG 17) to protect fragile ecosystems and ensure that development does not compromise the region's environmental health.","encabezado":"Conexión Territorial y Diagnóstico Preciso","pos":7,"enabled":true,"warn":null},{"sec":"hicimos","text":"Una Narrativa de Impacto Coherente. Las acciones de la Universidad de Santander no son esfuerzos aislados. Configuran una narrativa coherente de impacto que vincula la protección de nuestros recursos naturales (Día de la Tierra) con la provisión de soluciones tecnológicas de vanguardia (Estufa de Hidrógeno).","text_en":"A Coherent Impact Narrative. The actions of the University of Santander are not isolated efforts. They form a coherent impact narrative that links the protection of our natural resources (Earth Day) with the provision of cutting-edge technological solutions (Hydrogen Stove).","encabezado":"Una Narrativa de Impacto Coherente","pos":8,"enabled":true,"warn":null},{"sec":"hicimos","text":"Eficiencia: Pasamos del diagnóstico (Caño El Pital) a la solución aplicada (Río Fonce).","text_en":"Efficiency: We move from diagnosis (Caño El Pital) to applied solution (Río Fonce).","pos":9,"enabled":true,"warn":null},{"sec":"hicimos","text":"Conexión: Creamos puentes entre instituciones (UPC), el gobierno (Ministerio de Minas) y escenarios globales (COP16).","text_en":"Connection: We build bridges between institutions (UPC), government (Ministry of Mines) and global forums (COP16).","pos":10,"enabled":true,"warn":null},{"sec":"hicimos","text":"Humanismo: Ponemos la ciencia al servicio de las necesidades básicas (agua limpia, energía para cocinar) de las comunidades.","text_en":"Humanism: We put science at the service of communities' basic needs (clean water, energy for cooking).","pos":11,"enabled":true,"warn":null},{"sec":"hicimos","text":"La UDES demuestra con hechos su compromiso con los ODS, integrando la sostenibilidad en su ADN y probando que es posible generar un impacto positivo, medible y profundamente humano.","text_en":"UDES demonstrates through action its commitment to the SDGs, embedding sustainability in its DNA and proving that it is possible to generate positive, measurable and deeply human impact.","pos":12,"enabled":true,"warn":null}],"conteo":{"tesis":1,"cifras":0,"hicimos":11,"proyectos":0,"viene":0,"cifras_figs":0,"videos":0,"enlaces":0,"copiados":0,"deshabilitados":0},"rarezas":["Sin «próximos pasos» en el HTML: el informe no tiene sección «viene».","Sin cifras destacadas importables."]}$ods_json$::jsonb,
$ods_html$<!DOCTYPE html>
<html lang="es">
<head>
  <meta charset="UTF-8" />
  <meta name="viewport" content="width=device-width, initial-scale=1.0" />
  <title>ODS 6 · Agua limpia y saneamiento | Informe</title>
  <meta name="description" content="Plantilla base para informes ODS 6. Encabezado y secciones en blanco para completar." />
  <link href="https://fonts.googleapis.com/css2?family=Inter:wght@400;600;700&display=swap" rel="stylesheet">
  <style>
    :root { --sdg-accent: #26BDE2; --sdg-accent-light: rgba(38,189,226,0.12); --text-primary: #2c3e50; --text-secondary: #546e7a; --bg-white: #ffffff; --border-light: #e8eaed; --shadow-sm: 0 1px 3px rgba(0,0,0,0.04);} * { box-sizing: border-box; margin: 0; padding: 0; } body { font-family: 'Inter', system-ui, -apple-system, Segoe UI, Roboto, Arial, sans-serif; color: var(--text-primary); background: var(--bg-white); } .container { max-width: 1160px; margin: 0 auto; padding: 0 28px; } .lang-switch { position: fixed; top: 16px; right: 16px; z-index: 110; display:flex; gap:8px; background:#f6f7f8; padding:4px; border-radius:10px; } .lang-switch button { border:0; background:transparent; padding:8px 14px; border-radius:7px; font-weight:600; color:var(--text-secondary); cursor:pointer; } .lang-switch button.active { background:#fff; color:var(--sdg-accent); box-shadow: var(--shadow-sm); } .hero { padding: 88px 0 72px; background: radial-gradient(circle at 50% 0%, var(--sdg-accent-light) 0%, #ffffff 65%); border-bottom:1px solid var(--border-light); clip-path: polygon(0 0, 100% 0, 100% 92%, 50% 100%, 0 92%); } .grid-2 { display:grid; grid-template-columns: 1.2fr 0.8fr; gap:32px; align-items:center; } .eyebrow { color: var(--sdg-accent); text-transform: uppercase; font-weight: 700; letter-spacing: .12em; font-size:12px; margin-bottom: 12px; display:inline-block; } h1 { font-size: clamp(32px, 5vw, 52px); line-height: 1.15; margin: 0 0 8px 0; } .hero-illustration { width:100%; height:auto; max-width:360px; margin:0 auto; display:block; border-radius:16px; } section { padding: 64px 0; } .section-title { font-size: clamp(24px, 3.5vw, 34px); margin-bottom: 8px; font-weight: 700; } .section-rule { height: 1px; background: var(--border-light); margin: 16px 0 24px; } footer { border-top:1px solid var(--border-light); padding: 28px 0; color:#6b7b86; }
    /* Lead / intro paragraph styling */
    .lead { font-size: 18px; color: var(--text-secondary); margin-top: 8px; line-height: 1.7; }
    .lead.justified { text-align: justify; }
    /* Light blue gradient over a background image for full-width section; inner panel kept neutral */
    #agua-eje-vida {
      position: relative;
      /* image as the base layer; overlays will be added with ::before */
      background-image: url('https://udes.edu.co/media/k2/items/cache/01b2e40d82ca45a6dda123a1e5fb3ac1_XL.jpg');
      background-size: cover;
      background-position: center top;
      background-repeat: no-repeat;
      overflow: hidden;
    }
    /* overlay: gradient + bluish-white tint at 30% opacity to mute the image */
    #agua-eje-vida::before {
      content: "";
      position: absolute;
      inset: 0;
      /* stronger bluish-white overlay (70% opacity) to mute the background image */
      background: linear-gradient(180deg, rgba(38,189,226,0.14), rgba(38,189,226,0.06)), rgba(240,248,255,0.7);
      pointer-events: none;
      z-index: 0;
    }
    #agua-eje-vida .container { position: relative; z-index: 1; padding-top: 36px; padding-bottom: 36px; }
  .panel-blue { background: transparent; border: none; padding: 0; border-radius: 0; }
  .panel-blue h3 { color: var(--sdg-accent); margin-top: 0; }
  .panel-blue .muted { color: var(--text-secondary); }
  /* Accent title style for white sections */
  .accent-title { color: var(--sdg-accent); margin-top: 0; font-size: clamp(20px, 2.4vw, 28px); }
  </style>
</head>
