values (8, 2025, 'sdgudes.github.io', $ods_json${"ods":8,"edicion":2025,"fuente":"sdgudes.github.io","archivo":"ods8_informe.html","titulo":{"es":"ODS 8: Trabajo decente y crecimiento económico","en":"SDG 8: Decent Work and Economic Growth"},"tesis":[{"es":"El Objetivo de Desarrollo Sostenible 8 es la piedra angular para la prosperidad y la dignidad humana. No se trata simplemente de crear empleo, sino de fomentar un crecimiento económico sostenido, inclusivo y sostenible, que formalice las oportunidades y promueva la innovación. Para la Universidad de Santander (UDES), este objetivo es una hoja de ruta para transformar el potencial de nuestra región en oportunidades tangibles. Actuamos como un motor de desarrollo, generando eficiencia en nuestros emprendedores, conexión en el ecosistema empresarial y humanismo al poner el foco en la economía popular y el fortalecimiento del tejido social.","en":"Sustainable Development Goal 8 is the cornerstone for prosperity and human dignity. It is not simply about creating jobs, but about fostering sustained, inclusive and sustainable economic growth that formalizes opportunities and promotes innovation. For the Universidad de Santander (UDES), this goal is a roadmap to transform our region's potential into tangible opportunities. We act as an engine of development, generating efficiency among our entrepreneurs, connectivity within the business ecosystem, and humanism by focusing on the popular economy and strengthening the social fabric."}],"cifras":[{"v":"+250","etiqueta":{"es":"Participantes Feria \"Yo Emprendo\"","en":"External Entrepreneurship Support"},"nota":{"es":"IV Feria \"Yo Emprendo 2024\"","en":"IV Fair \"Yo Emprendo 2024\""}},{"v":"103","etiqueta":{"es":"Emprendedores certificados (Economía Popular)","en":"Popular Economy Certification"},"nota":{"es":"Diplomado","en":"Diploma Program"}},{"v":"30","etiqueta":{"es":"Emprendimientos verdes y sostenibles","en":"Green Ventures"},"nota":{"es":"Feria Empresarial","en":"Business Fair"}},{"v":"78%","etiqueta":{"es":"Tasa de empleabilidad de egresados","en":"Graduate Employability"},"nota":{"es":"Promoción 2024","en":"Class of 2024"}},{"v":"+320","etiqueta":{"es":"Estudiantes ubicados en prácticas profesionales","en":"Professional Internships"},"nota":{"es":"2025-I","en":"2025-I"}},{"v":"1,240","etiqueta":{"es":"Colaboradores directos (docentes y administrativos)","en":"Employer Commitment"},"nota":{"es":"Personal total","en":"Direct staff"}},{"v":"100%","etiqueta":{"es":"Cobertura SG-SST (Seguridad y Salud en el Trabajo)","en":"SG-SST Coverage"},"nota":{"es":"Planta con cobertura","en":"Work safety coverage"}}],"cifras_no_importadas":[],"videos":[],"enlaces":[],"imagenes":[{"src":"https://sdgbook.com/wp-content/uploads/sites/2/2019/09/8.png","alt":{"es":"Logo ODS 8","en":"Logo ODS 8"},"pie":{"es":"","en":""},"tipo":"ilustracion-ods","zona":"portada"}],"fotos_udes":[],"graficos":[],"secciones":[{"titulo":{"es":"","en":""},"piezas":[{"t":"imagen","zona":"portada","src":"https://sdgbook.com/wp-content/uploads/sites/2/2019/09/8.png","alt":{"es":"Logo ODS 8","en":"Logo ODS 8"},"pie":{"es":"","en":""},"tipo":"ilustracion-ods"},{"t":"parrafo","zona":"cuerpo","texto":{"es":"El Objetivo de Desarrollo Sostenible 8 es la piedra angular para la prosperidad y la dignidad humana. No se trata simplemente de crear empleo, sino de fomentar un crecimiento económico sostenido, inclusivo y sostenible, que formalice las oportunidades y promueva la innovación. Para la Universidad de Santander (UDES), este objetivo es una hoja de ruta para transformar el potencial de nuestra región en oportunidades tangibles. Actuamos como un motor de desarrollo, generando eficiencia en nuestros emprendedores, conexión en el ecosistema empresarial y humanismo al poner el foco en la economía popular y el fortalecimiento del tejido social.","en":"Sustainable Development Goal 8 is the cornerstone for prosperity and human dignity. It is not simply about creating jobs, but about fostering sustained, inclusive and sustainable economic growth that formalizes opportunities and promotes innovation. For the Universidad de Santander (UDES), this goal is a roadmap to transform our region's potential into tangible opportunities. We act as an engine of development, generating efficiency among our entrepreneurs, connectivity within the business ecosystem, and humanism by focusing on the popular economy and strengthening the social fabric."}},{"t":"cifra","zona":"cuerpo","v":"+250","etiqueta":{"es":"Participantes Feria \"Yo Emprendo\"","en":"External Entrepreneurship Support"},"nota":{"es":"IV Feria \"Yo Emprendo 2024\"","en":"IV Fair \"Yo Emprendo 2024\""},"contador":false,"numerica":true},{"t":"cifra","zona":"cuerpo","v":"103","etiqueta":{"es":"Emprendedores certificados (Economía Popular)","en":"Popular Economy Certification"},"nota":{"es":"Diplomado","en":"Diploma Program"},"contador":false,"numerica":true},{"t":"cifra","zona":"cuerpo","v":"30","etiqueta":{"es":"Emprendimientos verdes y sostenibles","en":"Green Ventures"},"nota":{"es":"Feria Empresarial","en":"Business Fair"},"contador":false,"numerica":true},{"t":"cifra","zona":"cuerpo","v":"78%","etiqueta":{"es":"Tasa de empleabilidad de egresados","en":"Graduate Employability"},"nota":{"es":"Promoción 2024","en":"Class of 2024"},"contador":false,"numerica":true},{"t":"cifra","zona":"cuerpo","v":"+320","etiqueta":{"es":"Estudiantes ubicados en prácticas profesionales","en":"Professional Internships"},"nota":{"es":"2025-I","en":"2025-I"},"contador":false,"numerica":true},{"t":"cifra","zona":"cuerpo","v":"1,240","etiqueta":{"es":"Colaboradores directos (docentes y administrativos)","en":"Employer Commitment"},"nota":{"es":"Personal total","en":"Direct staff"},"contador":false,"numerica":true},{"t":"cifra","zona":"cuerpo","v":"100%","etiqueta":{"es":"Cobertura SG-SST (Seguridad y Salud en el Trabajo)","en":"SG-SST Coverage"},"nota":{"es":"Planta con cobertura","en":"Work safety coverage"},"contador":false,"numerica":true}]},{"titulo":{"es":"Eficiencia: La Metodología del Éxito","en":"Efficiency: The Methodology of Success"},"piezas":[{"t":"parrafo","zona":"cuerpo","texto":{"es":"Nuestra conexión se traduce en plataformas eficientes para la acción. No solo discutimos sobre el emprendimiento; lo cultivamos sistemáticamente. Hemos desarrollado un ecosistema que guía al emprendedor desde la idea hasta el mercado.","en":"Our connectivity translates into efficient platforms for action. We don't just discuss entrepreneurship; we cultivate it systematically. We've developed an ecosystem that guides the entrepreneur from idea to market."}},{"t":"titulo","zona":"cuerpo","nivel":4,"texto":{"es":"Formación y Metodología","en":"Training and Methodology"}},{"t":"parrafo","zona":"cuerpo","texto":{"es":"Iniciativas como la Ruta RUGEE y su taller \"Decidí emprender\" socializan una metodología clara para la creación de empresas. Esta formación se consolida con programas de alto impacto, como el Diplomado en Fortalecimiento de las Unidades Productivas de la Economía Popular, que certificó a 103 emprendedores locales, dotándolos de herramientas reales.","en":"Initiatives such as the Ruta RUGEE and its workshop \"I Decided to Start\" disseminate a clear methodology for company creation. This training is consolidated with high-impact programs, such as the Diploma in Strengthening Productive Units of the Popular Economy, which certified 103 local entrepreneurs, equipping them with real tools."}},{"t":"titulo","zona":"cuerpo","nivel":4,"texto":{"es":"Plataformas de Visibilidad","en":"Platforms of Visibility"}},{"t":"parrafo","zona":"cuerpo","texto":{"es":"Materializamos las ideas. La IV Feria Internacional de Emprendimiento \"Yo Emprendo 2024\" se consolidó como una plataforma esencial, reuniendo a más de 250 emprendedores. Paralelamente, la Feria Empresarial para la Economía Popular sirvió de vitrina para 30 emprendimientos verdes y sostenibles surgidos de nuestro diplomado.","en":"We materialize ideas. The IV International Entrepreneurship Fair \"Yo Emprendo 2024\" consolidated as an essential platform, bringing together over 250 entrepreneurs. At the same time, the Business Fair for the Popular Economy showcased 30 green and sustainable ventures that emerged from our diploma program."}},{"t":"titulo","zona":"cuerpo","nivel":4,"texto":{"es":"Resultados Medibles","en":"Measurable Results"}},{"t":"parrafo","zona":"cuerpo","texto":{"es":"Nuestro modelo funciona. El éxito de nuestros estudiantes, como el segundo puesto obtenido en el Santander IGNITION LAB, demuestra la capacidad tecnológica e innovadora que estamos cultivando.","en":"Our model works. The success of our students, such as the second place achieved in the Santander IGNITION LAB, demonstrates the technological and innovative capacity we are cultivating."}}]},{"titulo":{"es":"Conexión Estratégica: El Ecosistema del Progreso","en":"Strategic Connectivity: The Ecosystem of Progress"},"piezas":[{"t":"parrafo","zona":"cuerpo","texto":{"es":"La UDES es el nexo que une a los actores clave del desarrollo. No esperamos el cambio; lo convocamos y lo articulamos. Nuestra vocación de articuladores se demuestra al ser el escenario donde la academia, la empresa y el Estado dialogan y trazan objetivos comunes.","en":"UDES is the nexus that brings together the key actors of development. We do not wait for change; we convene and articulate it. Our role as conveners is demonstrated by being the stage where academia, industry and government dialog and set shared objectives."}},{"t":"parrafo","zona":"cuerpo","texto":{"es":"Eventos como el Foro Económico Regional y Empresarial de Santander (FERES 2024) y el \"Panel de Sinergias: Empresa, Academia y Estado\" son la prueba de nuestra capacidad para crear el diálogo estratégico.","en":"Events such as the Santander Regional and Business Economic Forum (FERES 2024) and the \"Synergies Panel: Business, Academia and Government\" are proof of our capacity to create strategic dialogue."}},{"t":"parrafo","zona":"cuerpo","texto":{"es":"Lideramos la conversación sectorial, como se vio en la reunión de la Mesa de Economía Popular y Solidaria de Santander durante nuestro VI Congreso de MiPyME, y al ser anfitriones de las mesas de trabajo para la nueva Ley del Deporte, reconociendo su impacto en la economía y el bienestar.","en":"We lead the sectoral conversation, as seen in the meeting of the Popular and Solidarity Economy Table of Santander during our VI MiPyME Congress, and by hosting working groups for the new Sports Law, recognizing its impact on the economy and well-being."}},{"t":"parrafo","zona":"cuerpo","texto":{"es":"Conectamos a nuestros emprendedores con el mundo a través de eventos como \"Viviendo la mentoría\", un encuentro digital con expertos nacionales e internacionales en innovación.","en":"We connect our entrepreneurs to the world through events like \"Living Mentorship\", a digital gathering with national and international innovation experts."}}]},{"titulo":{"es":"Humanismo: El Rostro del Crecimiento Económico","en":"Humanism: The Face of Economic Growth"},"piezas":[{"t":"parrafo","zona":"cuerpo","texto":{"es":"El crecimiento económico carece de sentido si no fortalece el tejido social. El humanismo es el \"por qué\" de nuestra labor. Detrás de cada estadística hay una historia de vida, una familia y una tradición.","en":"Economic growth is meaningless if it does not strengthen the social fabric. Humanism is the \"why\" behind our work. Behind every statistic is a life story, a family and a tradition."}},{"t":"titulo","zona":"cuerpo","nivel":4,"texto":{"es":"Impacto Comunitario","en":"Community Impact"}},{"t":"parrafo","zona":"cuerpo","texto":{"es":"Proyectos de proyección social como \"Maquilando Felicidad\" en Piedecuesta demuestran nuestro enfoque integral. Allí, no solo fomentamos unidades productivas, sino que fortalecemos la empleabilidad juvenil y la cohesión comunitaria.","en":"Social outreach projects such as \"Maquilando Felicidad\" in Piedecuesta demonstrate our comprehensive approach. There, we not only foster productive units but also strengthen youth employability and community cohesion."}},{"t":"titulo","zona":"cuerpo","nivel":4,"texto":{"es":"Preservación de la Tradición","en":"Preservation of Tradition"}},{"t":"parrafo","zona":"cuerpo","texto":{"es":"Celebramos las historias que dan identidad a nuestra región. Apoyamos a emprendedoras como Libia Vesga y su \"Cacao Macaregua\" en Lebrija, quien no solo genera valor agregado, sino que preserva una tradición cacaotera que es el sustento de cientos de familias.","en":"We celebrate the stories that give identity to our region. We support entrepreneurs such as Libia Vesga and her \"Cacao Macaregua\" in Lebrija, who not only generate added value but also preserve a cacao tradition that sustains hundreds of families."}},{"t":"titulo","zona":"cuerpo","nivel":4,"texto":{"es":"Reconocimiento","en":"Recognition"}},{"t":"parrafo","zona":"cuerpo","texto":{"es":"Entendemos que el desarrollo económico es, ante todo, un acto de dignidad. Por ello, culminamos nuestros esfuerzos con la \"Gala de Logros de la Economía Popular y Solidaria\", un evento para reconocer y celebrar el esfuerzo de los emprendedores que, con el apoyo de la UDES, fortalecen el sector más vital de nuestra economía.","en":"We understand that economic development is, above all, an act of dignity. Therefore, we culminate our efforts with the \"Gala of Achievements of the Popular and Solidarity Economy\", an event to recognize and celebrate the efforts of entrepreneurs who, with the support of UDES, strengthen the most vital sector of our economy."}}]}],"bloques":[{"sec":"tesis","text":"El Objetivo de Desarrollo Sostenible 8 es la piedra angular para la prosperidad y la dignidad humana. No se trata simplemente de crear empleo, sino de fomentar un crecimiento económico sostenido, inclusivo y sostenible, que formalice las oportunidades y promueva la innovación. Para la Universidad de Santander (UDES), este objetivo es una hoja de ruta para transformar el potencial de nuestra región en oportunidades tangibles. Actuamos como un motor de desarrollo, generando eficiencia en nuestros emprendedores, conexión en el ecosistema empresarial y humanismo al poner el foco en la economía popular y el fortalecimiento del tejido social.","text_en":"Sustainable Development Goal 8 is the cornerstone for prosperity and human dignity. It is not simply about creating jobs, but about fostering sustained, inclusive and sustainable economic growth that formalizes opportunities and promotes innovation. For the Universidad de Santander (UDES), this goal is a roadmap to transform our region's potential into tangible opportunities. We act as an engine of development, generating efficiency among our entrepreneurs, connectivity within the business ecosystem, and humanism by focusing on the popular economy and strengthening the social fabric.","pos":1,"enabled":true,"warn":null},{"sec":"cifras","text":"ODS 8: Trabajo decente y crecimiento económico.","text_en":"SDG 8: Decent Work and Economic Growth.","figs":[{"v":"+250","label":"Participantes Feria \"Yo Emprendo\"","src":"Informe 2025","v_en":"+250","label_en":"External Entrepreneurship Support","note":"IV Feria \"Yo Emprendo 2024\"","note_en":"IV Fair \"Yo Emprendo 2024\""},{"v":"103","label":"Emprendedores certificados (Economía Popular)","src":"Informe 2025","v_en":"103","label_en":"Popular Economy Certification","note":"Diplomado","note_en":"Diploma Program"},{"v":"30","label":"Emprendimientos verdes y sostenibles","src":"Informe 2025","v_en":"30","label_en":"Green Ventures","note":"Feria Empresarial","note_en":"Business Fair"},{"v":"78 %","label":"Tasa de empleabilidad de egresados","src":"Informe 2025","v_en":"78%","label_en":"Graduate Employability","note":"Promoción 2024","note_en":"Class of 2024"},{"v":"+320","label":"Estudiantes ubicados en prácticas profesionales","src":"Informe 2025","v_en":"+320","label_en":"Professional Internships","note":"2025-I","note_en":"2025-I"},{"v":"1.240","label":"Colaboradores directos (docentes y administrativos)","src":"Informe 2025","v_en":"1,240","label_en":"Employer Commitment","note":"Personal total","note_en":"Direct staff"},{"v":"100 %","label":"Cobertura SG-SST (Seguridad y Salud en el Trabajo)","src":"Informe 2025","v_en":"100%","label_en":"SG-SST Coverage","note":"Planta con cobertura","note_en":"Work safety coverage"}],"pos":2,"enabled":true,"warn":null},{"sec":"hicimos","text":"Eficiencia: La Metodología del Éxito. Nuestra conexión se traduce en plataformas eficientes para la acción. No solo discutimos sobre el emprendimiento; lo cultivamos sistemáticamente. Hemos desarrollado un ecosistema que guía al emprendedor desde la idea hasta el mercado.","text_en":"Efficiency: The Methodology of Success. Our connectivity translates into efficient platforms for action. We don't just discuss entrepreneurship; we cultivate it systematically. We've developed an ecosystem that guides the entrepreneur from idea to market.","encabezado":"Eficiencia: La Metodología del Éxito","pos":3,"enabled":true,"warn":null},{"sec":"hicimos","text":"Formación y Metodología. Iniciativas como la Ruta RUGEE y su taller \"Decidí emprender\" socializan una metodología clara para la creación de empresas. Esta formación se consolida con programas de alto impacto, como el Diplomado en Fortalecimiento de las Unidades Productivas de la Economía Popular, que certificó a 103 emprendedores locales, dotándolos de herramientas reales.","text_en":"Training and Methodology. Initiatives such as the Ruta RUGEE and its workshop \"I Decided to Start\" disseminate a clear methodology for company creation. This training is consolidated with high-impact programs, such as the Diploma in Strengthening Productive Units of the Popular Economy, which certified 103 local entrepreneurs, equipping them with real tools.","encabezado":"Formación y Metodología","pos":4,"enabled":true,"warn":null},{"sec":"hicimos","text":"Plataformas de Visibilidad. Materializamos las ideas. La IV Feria Internacional de Emprendimiento \"Yo Emprendo 2024\" se consolidó como una plataforma esencial, reuniendo a más de 250 emprendedores. Paralelamente, la Feria Empresarial para la Economía Popular sirvió de vitrina para 30 emprendimientos verdes y sostenibles surgidos de nuestro diplomado.","text_en":"Platforms of Visibility. We materialize ideas. The IV International Entrepreneurship Fair \"Yo Emprendo 2024\" consolidated as an essential platform, bringing together over 250 entrepreneurs. At the same time, the Business Fair for the Popular Economy showcased 30 green and sustainable ventures that emerged from our diploma program.","encabezado":"Plataformas de Visibilidad","pos":5,"enabled":true,"warn":null},{"sec":"hicimos","text":"Resultados Medibles. Nuestro modelo funciona. El éxito de nuestros estudiantes, como el segundo puesto obtenido en el Santander IGNITION LAB, demuestra la capacidad tecnológica e innovadora que estamos cultivando.","text_en":"Measurable Results. Our model works. The success of our students, such as the second place achieved in the Santander IGNITION LAB, demonstrates the technological and innovative capacity we are cultivating.","encabezado":"Resultados Medibles","pos":6,"enabled":true,"warn":null},{"sec":"hicimos","text":"Conexión Estratégica: El Ecosistema del Progreso. La UDES es el nexo que une a los actores clave del desarrollo. No esperamos el cambio; lo convocamos y lo articulamos. Nuestra vocación de articuladores se demuestra al ser el escenario donde la academia, la empresa y el Estado dialogan y trazan objetivos comunes.","text_en":"Strategic Connectivity: The Ecosystem of Progress. UDES is the nexus that brings together the key actors of development. We do not wait for change; we convene and articulate it. Our role as conveners is demonstrated by being the stage where academia, industry and government dialog and set shared objectives.","encabezado":"Conexión Estratégica: El Ecosistema del Progreso","pos":7,"enabled":true,"warn":null},{"sec":"hicimos","text":"Eventos como el Foro Económico Regional y Empresarial de Santander (FERES 2024) y el \"Panel de Sinergias: Empresa, Academia y Estado\" son la prueba de nuestra capacidad para crear el diálogo estratégico.","text_en":"Events such as the Santander Regional and Business Economic Forum (FERES 2024) and the \"Synergies Panel: Business, Academia and Government\" are proof of our capacity to create strategic dialogue.","pos":8,"enabled":true,"warn":null},{"sec":"hicimos","text":"Lideramos la conversación sectorial, como se vio en la reunión de la Mesa de Economía Popular y Solidaria de Santander durante nuestro VI Congreso de MiPyME, y al ser anfitriones de las mesas de trabajo para la nueva Ley del Deporte, reconociendo su impacto en la economía y el bienestar.","text_en":"We lead the sectoral conversation, as seen in the meeting of the Popular and Solidarity Economy Table of Santander during our VI MiPyME Congress, and by hosting working groups for the new Sports Law, recognizing its impact on the economy and well-being.","pos":9,"enabled":true,"warn":null},{"sec":"hicimos","text":"Conectamos a nuestros emprendedores con el mundo a través de eventos como \"Viviendo la mentoría\", un encuentro digital con expertos nacionales e internacionales en innovación.","text_en":"We connect our entrepreneurs to the world through events like \"Living Mentorship\", a digital gathering with national and international innovation experts.","pos":10,"enabled":true,"warn":null},{"sec":"hicimos","text":"Humanismo: El Rostro del Crecimiento Económico. El crecimiento económico carece de sentido si no fortalece el tejido social. El humanismo es el \"por qué\" de nuestra labor. Detrás de cada estadística hay una historia de vida, una familia y una tradición.","text_en":"Humanism: The Face of Economic Growth. Economic growth is meaningless if it does not strengthen the social fabric. Humanism is the \"why\" behind our work. Behind every statistic is a life story, a family and a tradition.","encabezado":"Humanismo: El Rostro del Crecimiento Económico","pos":11,"enabled":true,"warn":null},{"sec":"hicimos","text":"Impacto Comunitario. Proyectos de proyección social como \"Maquilando Felicidad\" en Piedecuesta demuestran nuestro enfoque integral. Allí, no solo fomentamos unidades productivas, sino que fortalecemos la empleabilidad juvenil y la cohesión comunitaria.","text_en":"Community Impact. Social outreach projects such as \"Maquilando Felicidad\" in Piedecuesta demonstrate our comprehensive approach. There, we not only foster productive units but also strengthen youth employability and community cohesion.","encabezado":"Impacto Comunitario","pos":12,"enabled":true,"warn":null},{"sec":"hicimos","text":"Preservación de la Tradición. Celebramos las historias que dan identidad a nuestra región. Apoyamos a emprendedoras como Libia Vesga y su \"Cacao Macaregua\" en Lebrija, quien no solo genera valor agregado, sino que preserva una tradición cacaotera que es el sustento de cientos de familias.","text_en":"Preservation of Tradition. We celebrate the stories that give identity to our region. We support entrepreneurs such as Libia Vesga and her \"Cacao Macaregua\" in Lebrija, who not only generate added value but also preserve a cacao tradition that sustains hundreds of families.","encabezado":"Preservación de la Tradición","pos":13,"enabled":true,"warn":null},{"sec":"hicimos","text":"Reconocimiento. Entendemos que el desarrollo económico es, ante todo, un acto de dignidad. Por ello, culminamos nuestros esfuerzos con la \"Gala de Logros de la Economía Popular y Solidaria\", un evento para reconocer y celebrar el esfuerzo de los emprendedores que, con el apoyo de la UDES, fortalecen el sector más vital de nuestra economía.","text_en":"Recognition. We understand that economic development is, above all, an act of dignity. Therefore, we culminate our efforts with the \"Gala of Achievements of the Popular and Solidarity Economy\", an event to recognize and celebrate the efforts of entrepreneurs who, with the support of UDES, strengthen the most vital sector of our economy.","encabezado":"Reconocimiento","pos":14,"enabled":true,"warn":null}],"conteo":{"tesis":1,"cifras":1,"hicimos":12,"proyectos":0,"viene":0,"cifras_figs":7,"videos":0,"enlaces":0,"copiados":0,"deshabilitados":0},"rarezas":["Las cifras no tienen frase que las presente: el bloque de cifras lleva el título de su sección.","Sin «próximos pasos» en el HTML: el informe no tiene sección «viene»."]}$ods_json$::jsonb,
$ods_html$<!DOCTYPE html>
<html lang="es">
<head>
  <meta charset="UTF-8" />
  <meta name="viewport" content="width=device-width, initial-scale=1.0" />
  <title>ODS 8 · Trabajo decente y crecimiento económico | Informe</title>
  <meta name="description" content="Plantilla base para informes ODS 8. Encabezado y secciones en blanco para completar." />
  <link href="https://fonts.googleapis.com/css2?family=Inter:wght@400;600;700&display=swap" rel="stylesheet">
  <style>
    :root { --sdg-accent: #A21942; --sdg-accent-light: rgba(162,25,66,0.12); --text-primary: #2c3e50; --text-secondary: #546e7a; --bg-white: #ffffff; --border-light: #e8eaed; --shadow-sm: 0 1px 3px rgba(0,0,0,0.04);} * { box-sizing: border-box; margin: 0; padding: 0; } body { font-family: 'Inter', system-ui, -apple-system, Segoe UI, Roboto, Arial, sans-serif; color: var(--text-primary); background: var(--bg-white); } .container { max-width: 1160px; margin: 0 auto; padding: 0 28px; } .lang-switch { position: fixed; top: 16px; right: 16px; z-index: 110; display:flex; gap:8px; background:#f6f7f8; padding:4px; border-radius:10px; } .lang-switch button { border:0; background:transparent; padding:8px 14px; border-radius:7px; font-weight:600; color:var(--text-secondary); cursor:pointer; } .lang-switch button.active { background:#fff; color:var(--sdg-accent); box-shadow: var(--shadow-sm); } .hero { padding: 88px 0 72px; background: radial-gradient(circle at 50% 0%, var(--sdg-accent-light) 0%, #ffffff 65%); border-bottom:1px solid var(--border-light); clip-path: polygon(0 0, 100% 0, 100% 92%, 50% 100%, 0 92%); } .grid-2 { display:grid; grid-template-columns: 1.2fr 0.8fr; gap:32px; align-items:center; } .eyebrow { color: var(--sdg-accent); text-transform: uppercase; font-weight: 700; letter-spacing: .12em; font-size:12px; margin-bottom: 12px; display:inline-block; } h1 { font-size: clamp(32px, 5vw, 52px); line-height: 1.15; margin: 0 0 8px 0; } .hero-illustration { width:100%; height:auto; max-width:360px; margin:0 auto; display:block; border-radius:16px; } section { padding: 64px 0; } .section-title { font-size: clamp(24px, 3.5vw, 34px); margin-bottom: 8px; font-weight: 700; } .section-rule { height: 1px; background: var(--border-light); margin: 16px 0 24px; } footer { border-top:1px solid var(--border-light); padding: 28px 0; color:#6b7b86; }
    /* Barra de navegación ODS (v2) */
    .sdg-navbar { position: fixed; top: 0; left: 0; width: 100%; height: 8px; display: flex; z-index: 1000; background: transparent; }
    .sdg-nav-item { flex: 1; height: 8px; cursor: pointer; position: relative; transition: all 0.4s cubic-bezier(0.4, 0, 0.2, 1); text-decoration: none; display: flex; align-items: center; justify-content: center; overflow: hidden; }
    .sdg-nav-item::before { content: "ODS " attr(data-sdg); position: absolute; top: 50%; left: 50%; transform: translate(-50%, -50%); color: #fff; font-size: 10px; font-weight: 700; letter-spacing: 0.5px; z-index: 2; opacity: 1; transition: opacity 0.3s ease; pointer-events: none; text-shadow: 0 1px 2px rgba(0,0,0,0.2); }
    .sdg-nav-item:hover::before { opacity: 0; }
    .sdg-nav-item:hover { height: 320px; box-shadow: 0 4px 20px rgba(0,0,0,0.15); }
    .sdg-card { width: 100%; height: 100%; background: #fff; display: flex; flex-direction: column; opacity: 0; transition: opacity 0.3s ease 0.15s; }
    .sdg-nav-item:hover .sdg-card { opacity: 1; }
    .sdg-card-image { width: 100%; height: 220px; object-fit: contain; display: block; background: #fff; padding: 8px; }
    .sdg-card-content { padding: 16px; text-align: center; flex: 1; display: flex; flex-direction: column; justify-content: center; align-items: center; gap: 4px; }
    .sdg-card-number { font-size: 12px; font-weight: 700; text-transform: uppercase; letter-spacing: 1px; opacity: 0.9; }
    .sdg-card-title { font-size: 14px; font-weight: 600; color: #1a1a1a; margin: 0; line-height: 1.3; }
    /* Bilingüe para la barra */
    html[lang="es"] .lang-en { display: none !important; }
    html[lang="en"] .lang-es { display: none !important; }
    /* Paleta ODS */
    .sdg-1{background:#E5243B}.sdg-2{background:#DDA63A}.sdg-3{background:#4C9F38}.sdg-4{background:#C5192D}.sdg-5{background:#FF3A21}.sdg-6{background:#26BDE2}.sdg-7{background:#FCC30B}.sdg-8{background:#A21942}.sdg-9{background:#FD6925}.sdg-10{background:#DD1367}.sdg-11{background:#FD9D24}.sdg-12{background:#BF8B2E}.sdg-13{background:#3F7E44}.sdg-14{background:#0A97D9}.sdg-15{background:#56C02B}.sdg-16{background:#00689D}.sdg-17{background:#19486A}
    /* Utilidad bilingüe genérica */
    [data-lang-content]{display:none} [data-lang-content][data-visible="true"]{display:block}
    @media (max-width:768px){.sdg-nav-item:hover{height:280px}.sdg-card-image{height:180px;padding:6px}.sdg-card-content{padding:12px}.sdg-card-number{font-size:11px}.sdg-card-title{font-size:12px}}
  </style>
  <style>
    /* Local overrides: justify lead paragraphs */
    .lead.justified { text-align: justify; }
    /* Forzar visibilidad por idioma: ocultar por defecto */
    [data-lang-content]{display:none !important}
    /* Mostrar bloques activos: para elementos normales usar block, pero .capsules mantiene grid */
    [data-lang-content][data-visible="true"]{display:block !important}
    [data-lang-content].capsules[data-visible="true"]{display:grid !important}

    /* Cápsulas de impacto: pequeños cards con cifras e íconos */
    .capsules { grid-template-columns: repeat(3, minmax(0,1fr)); gap: 12px; margin: 14px 0 10px; align-items:stretch; }
    .capsule { 
      background: #fff; 
      border: 1px solid var(--border-light); 
      padding: 14px; 
      border-radius: 10px; 
      display:flex; 
      gap:12px; 
      align-items:center; 
      box-shadow: var(--shadow-sm); 
      min-height:88px;
      transition: all 0.3s ease;
      opacity: 0;
      transform: translateY(20px);
      animation: capsuleIn 0.6s ease forwards;
    }
    .capsule:hover { 
      transform: translateY(-4px); 
      box-shadow: 0 4px 12px rgba(162,25,66,0.15); 
      border-color: var(--sdg-accent-light);
    }
    .capsule:nth-child(1) { animation-delay: 0.1s; }
    .capsule:nth-child(2) { animation-delay: 0.2s; }
    .capsule:nth-child(3) { animation-delay: 0.3s; }
    .capsule:nth-child(4) { animation-delay: 0.4s; }
    .capsule:nth-child(5) { animation-delay: 0.5s; }
    .capsule:nth-child(6) { animation-delay: 0.6s; }
    .capsule:nth-child(7) { animation-delay: 0.7s; }
    @keyframes capsuleIn {
      to { opacity: 1; transform: translateY(0); }
    }
    .capsule .icon { 
      width:48px; 
      height:48px; 
      flex:0 0 48px; 
      display:flex; 
      align-items:center; 
      justify-content:center; 
      border-radius:8px; 
      background: var(--sdg-accent-light); 
      color: var(--sdg-accent); 
      font-size:20px;
      transition: transform 0.3s ease;
    }
    .capsule:hover .icon {
      transform: scale(1.1) rotate(5deg);
    }
    .capsule .meta { font-size:12px; color: var(--text-secondary); margin-bottom:6px; line-height:1.3; }
    .capsule .value { 
      font-size:18px; 
      font-weight:700; 
      color: var(--text-primary); 
      line-height:1.2; 
    }
    .capsule small { display:block; font-size:11px; color:var(--text-secondary); font-weight:600; margin-top:2px; }
    @media (max-width:900px){ .capsules{grid-template-columns:repeat(2,1fr);} }
    @media (max-width:520px){ .capsules{grid-template-columns:repeat(1,1fr);} .hero { padding: 48px 0 36px; } }
    /* Hero-like band used for emphasis between sections */
    .hero-band { padding: 64px 0; background: radial-gradient(circle at 50% 0%, var(--sdg-accent-light) 0%, #ffffff 65%); border-bottom:1px solid var(--border-light); }
    .hero-band .section-title { color: var(--sdg-accent); }
  </style>
</head>
