  <footer role="contentinfo"><div class="container"><div data-lang-content data-lang="es">© 2025 · Informe ODS 10 · Versión para uso académico.</div><div data-lang-content data-lang="en">© 2025 · SDG 10 Report · Academic use version.</div></div></footer>
  <script>
    // Conmutación de idioma con persistencia
    (function(){
      const KEY='ods-lang';
      const es=document.querySelector('[data-lang-btn="es"]');
      const en=document.querySelector('[data-lang-btn="en"]');
      const blocks=document.querySelectorAll('[data-lang-content]');
      function apply(lang){
        document.documentElement.setAttribute('lang',lang);
        blocks.forEach(el=>{
          const vis = el.getAttribute('data-lang')===lang;
          el.setAttribute('data-visible', vis?'true':'false');
        });
        es.classList.toggle('active',lang==='es');
        en.classList.toggle('active',lang==='en');
        es.setAttribute('aria-pressed',lang==='es');
        en.setAttribute('aria-pressed',lang==='en');
        localStorage.setItem(KEY,lang);
      }
      apply(localStorage.getItem(KEY) || 'es');
      es.addEventListener('click',()=>apply('es'));
      en.addEventListener('click',()=>apply('en'));
    })();
    // Activa automáticamente el ODS actual en la barra
    (function(){
      const m=(location.pathname||'').match(/ods(\d+)_informe\.html$/);
      const current=m?m[1]:null; if(!current) return;
      document.querySelectorAll('.sdg-nav-item').forEach(a=>{
        a.classList.toggle('active', a.getAttribute('data-sdg')===current);
      });
    })();
  </script>
  <script>
    // Animar contadores de las cápsulas cuando entran en vista
    (function(){
      const container = document.querySelector('.capsules');
      if(!container) return;
      const items = container.querySelectorAll('.value[data-target]');
      let played = false;

      function easeOutQuad(t){ return t*(2-t); }

      function animateNumber(el, from, to, duration=1000, suffix=''){
        const start = performance.now();
        function frame(now){
          const elapsed = now - start;
          const t = Math.min(1, elapsed / duration);
          const v = Math.round(from + (to - from) * easeOutQuad(t));
          el.textContent = v.toLocaleString() + suffix;
          if(t < 1) requestAnimationFrame(frame);
        }
        requestAnimationFrame(frame);
      }

      const io = new IntersectionObserver((entries)=>{
        entries.forEach(entry=>{
          if(entry.isIntersecting && !played){
            played = true;
            items.forEach(el=>{
              const target = el.getAttribute('data-target');
              const orig = el.textContent || '';
              const hasPlus = orig.includes('+');
              if(!isNaN(Number(target))){
                const suffix = hasPlus ? '+' : '';
                animateNumber(el, 0, Number(target), 1100, suffix);
              } else {
                // no es numérico: dejar tal cual
                el.textContent = target;
              }
            });
            io.disconnect();
          }
        });
      }, { threshold: 0.2 });

      io.observe(container);
    })();
  </script>
</body>
