   set parsed = excluded.parsed, raw_html = excluded.raw_html, imported_at = now()
 where public.ods_report_archive.parsed is distinct from excluded.parsed
    or public.ods_report_archive.raw_html is distinct from excluded.raw_html;

insert into public.ods_report_archive (ods, edition, source, parsed, raw_html)
values (15, 2025, 'sdgudes.github.io', $ods_json${"ods":15,"edicion":2025,"fuente":"sdgudes.github.io","archivo":"ods15_informe.html","titulo":{"es":"ODS 15: Vida de ecosistemas terrestres","en":"SDG 15: Life on Land"},"tesis":[{"es":"La Universidad de Santander (UDES) reafirma su compromiso misional con el entorno, asumiendo un rol de liderazgo en la implementación de los Objetivos de Desarrollo Sostenible (ODS) en la región. Como una de las instituciones líderes en sostenibilidad ambiental en el país, la UDES integra la protección del planeta en su quehacer diario.","en":"The University of Santander (UDES) reaffirms its mission-driven commitment to the environment, taking a leadership role in implementing the Sustainable Development Goals (SDGs) in the region. As one of the country's leading institutions in environmental sustainability, UDES integrates planet protection into its daily work."}],"cifras":[{"v":"4.758 KG","etiqueta":{"es":"Reducidos durante la jornada del \"día sin carro y sin moto\" en Bucaramanga, gracias a la participación activa de nuestra comunidad universitaria.","en":"Reduced during the \"car and motorcycle free day\" in Bucaramanga, thanks to the active participation of our university community."},"nota":{"es":"","en":""}},{"v":"300 KG","etiqueta":{"es":"Recolectados en la 19ª jornada de recolección de residuos pos consumo en Bucaramanga, liderada por la UDES para promover la sostenibilidad.","en":"Collected during the 19th post-consumption waste collection day in Bucaramanga, led by UDES to promote sustainability."},"nota":{"es":"","en":""}},{"v":"52","etiqueta":{"es":"Líderes comunales de Girón formados como promotores del cuidado del medio ambiente gracias a la alianza \"Comunidades Sostenibles\" entre la UDES y Veolia.","en":"Community leaders from Girón trained as promoters of environmental care thanks to the \"Sustainable Communities\" alliance between UDES and Veolia."},"nota":{"es":"","en":""}},{"v":"19 AÑOS","etiqueta":{"es":"De investigación del Laboratorio de Tejidos Vegetales UDES, protegiendo la biodiversidad agrícola y luchando contra la extinción de especies nativas de Santander mediante biotecnología.","en":"Years of research by the UDES Plant Tissue Laboratory, protecting agricultural biodiversity and combating the extinction of native Santander species through biotechnology."},"nota":{"es":"","en":""}},{"v":"16","etiqueta":{"es":"Nuevos pasantes del programa de Medicina Veterinaria entregados al país, fortaleciendo el capital humano dedicado al bienestar animal.","en":"New interns from the Veterinary Medicine program delivered to the country, strengthening human capital dedicated to animal welfare."},"nota":{"es":"","en":""}}],"cifras_no_importadas":[],"videos":[],"enlaces":[],"imagenes":[{"src":"https://sdgbook.com/wp-content/uploads/sites/2/2019/09/15.png","alt":{"es":"Logo ODS 15","en":"Logo ODS 15"},"pie":{"es":"","en":""},"tipo":"ilustracion-ods","zona":"portada"}],"fotos_udes":[],"graficos":[],"secciones":[{"titulo":{"es":"","en":""},"piezas":[{"t":"parrafo","zona":"portada","texto":{"es":"La Universidad de Santander (UDES) reafirma su compromiso misional con el entorno, asumiendo un rol de liderazgo en la implementación de los Objetivos de Desarrollo Sostenible (ODS) en la región. Como una de las instituciones líderes en sostenibilidad ambiental en el país, la UDES integra la protección del planeta en su quehacer diario.","en":"The University of Santander (UDES) reaffirms its mission-driven commitment to the environment, taking a leadership role in implementing the Sustainable Development Goals (SDGs) in the region. As one of the country's leading institutions in environmental sustainability, UDES integrates planet protection into its daily work."}},{"t":"imagen","zona":"portada","src":"https://sdgbook.com/wp-content/uploads/sites/2/2019/09/15.png","alt":{"es":"Logo ODS 15","en":"Logo ODS 15"},"pie":{"es":"","en":""},"tipo":"ilustracion-ods"}]},{"titulo":{"es":"Cifras sostenibles","en":"Sustainable figures"},"piezas":[{"t":"parrafo","zona":"cuerpo","texto":{"es":"En línea con nuestra política de transparencia y gestión basada en resultados, destacamos las siguientes cifras clave que resumen nuestro impacto directo en la promoción del ODS 15:","en":"In line with our policy of transparency and results-based management, we highlight the following key figures that summarise our direct impact in promoting SDG 15:"}},{"t":"cifra","zona":"cuerpo","v":"4.758 KG","etiqueta":{"es":"Reducidos durante la jornada del \"día sin carro y sin moto\" en Bucaramanga, gracias a la participación activa de nuestra comunidad universitaria.","en":"Reduced during the \"car and motorcycle free day\" in Bucaramanga, thanks to the active participation of our university community."},"nota":{"es":"","en":""},"contador":false,"numerica":true},{"t":"cifra","zona":"cuerpo","v":"300 KG","etiqueta":{"es":"Recolectados en la 19ª jornada de recolección de residuos pos consumo en Bucaramanga, liderada por la UDES para promover la sostenibilidad.","en":"Collected during the 19th post-consumption waste collection day in Bucaramanga, led by UDES to promote sustainability."},"nota":{"es":"","en":""},"contador":false,"numerica":true},{"t":"cifra","zona":"cuerpo","v":"52","etiqueta":{"es":"Líderes comunales de Girón formados como promotores del cuidado del medio ambiente gracias a la alianza \"Comunidades Sostenibles\" entre la UDES y Veolia.","en":"Community leaders from Girón trained as promoters of environmental care thanks to the \"Sustainable Communities\" alliance between UDES and Veolia."},"nota":{"es":"","en":""},"contador":false,"numerica":true},{"t":"cifra","zona":"cuerpo","v":"19 AÑOS","etiqueta":{"es":"De investigación del Laboratorio de Tejidos Vegetales UDES, protegiendo la biodiversidad agrícola y luchando contra la extinción de especies nativas de Santander mediante biotecnología.","en":"Years of research by the UDES Plant Tissue Laboratory, protecting agricultural biodiversity and combating the extinction of native Santander species through biotechnology."},"nota":{"es":"","en":""},"contador":false,"numerica":true},{"t":"cifra","zona":"cuerpo","v":"16","etiqueta":{"es":"Nuevos pasantes del programa de Medicina Veterinaria entregados al país, fortaleciendo el capital humano dedicado al bienestar animal.","en":"New interns from the Veterinary Medicine program delivered to the country, strengthening human capital dedicated to animal welfare."},"nota":{"es":"","en":""},"contador":false,"numerica":true}]},{"titulo":{"es":"Protección de la Biodiversidad y Ecosistemas Estratégicos","en":"Protection of Biodiversity and Strategic Ecosystems"},"piezas":[{"t":"parrafo","zona":"cuerpo","texto":{"es":"La UDES enfoca sus esfuerzos en la conservación activa de la riqueza natural de la región:","en":"UDES focuses its efforts on the active conservation of the region's natural wealth:"}},{"t":"item","zona":"cuerpo","texto":{"es":"Defensa de Ecosistemas Clave: La UDES reafirmó su compromiso con el medio ambiente participando activamente en la Cumbre de Páramos 2024 en Bucaramanga, un espacio vital para la protección de estos ecosistemas estratégicos.","en":"Defense of Key Ecosystems: UDES reaffirmed its commitment to the environment by actively participating in the 2024 Páramos Summit in Bucaramanga, a vital space for protecting these strategic ecosystems."}},{"t":"item","zona":"cuerpo","texto":{"es":"Conservación de Flora Nativa: Ante la amenaza de extinción de especies como las orquídeas santandereanas, el Laboratorio de Tejidos Vegetales UDES (con 19 años de trayectoria) utiliza la biotecnología para propagar in vitro especies de interés y proteger la biodiversidad.","en":"Conservation of Native Flora: Facing the threat of extinction of species such as Santander orchids, the UDES Plant Tissue Laboratory (with 19 years of experience) uses biotechnology to propagate in vitro species of interest and protect biodiversity."}},{"t":"item","zona":"cuerpo","texto":{"es":"Acción por el Agua: En alianza con la UPC, se desarrolla un diagnóstico sobre la calidad del agua en el Caño El Pital (Aguachica), fundamental para la salud del ecosistema local.","en":"Action for Water: In partnership with UPC, a diagnosis of water quality is being developed in Caño El Pital (Aguachica), fundamental for the health of the local ecosystem."}},{"t":"item","zona":"cuerpo","texto":{"es":"Restauración y Siembra: La universidad participó activamente en la jornada de siembra en conmemoración del Día del Árbol en el Batallón de Servicios #5 Mercedes Ábrego.","en":"Restoration and Planting: The university actively participated in the planting day commemorating Tree Day at Battalion of Services #5 Mercedes Ábrego."}}]},{"titulo":{"es":"Bienestar Animal como pilar del Ecosistema","en":"Animal Welfare as an Ecosystem Pillar"},"piezas":[{"t":"parrafo","zona":"cuerpo","texto":{"es":"Reconociendo que la fauna es parte integral de los ecosistemas, la UDES ha consolidado una robusta estrategia de bienestar animal a través de la academia y la extensión:","en":"Recognising that fauna is an integral part of ecosystems, UDES has consolidated a robust animal welfare strategy through academia and outreach:"}},{"t":"item","zona":"cuerpo","texto":{"es":"Alianzas Estratégicas: La Clínica Veterinaria UDES ha fortalecido su servicio a la comunidad mediante alianzas clave con Kahu, para ampliar los servicios al sector externo, y con Cajasan, consolidando una colaboración de más de un año para ofrecer descuentos y asistencia.","en":"Strategic Alliances: The UDES Veterinary Clinic has strengthened its community service through key alliances with Kahu, to expand services to the external sector, and with Cajasan, consolidating a collaboration of over a year to offer discounts and assistance."}},{"t":"item","zona":"cuerpo","texto":{"es":"Formación de Alta Calidad: Se entregaron 16 nuevos pasantes de Medicina Veterinaria en la conmemoración de su día. Además, se promueve la excelencia académica con movilidades internacionales de estudiantes a instituciones de prestigio como la Universidad de Pisa en Italia.","en":"High-quality Training: 16 new Veterinary Medicine interns were delivered on their day of commemoration. In addition, academic excellence is promoted with international student mobilities to prestigious institutions such as the University of Pisa in Italy."}},{"t":"item","zona":"cuerpo","texto":{"es":"Sensibilización y Extensión: Se lideran iniciativas como el proyecto \"Capacita tu barrio\" para promover la tenencia responsable de mascotas. Adicionalmente, se lanzó el programa \"Cuidado Animal\" en el Canal UTV, un espacio de asesoría experta emitido semanalmente, y se inauguró la exposición fotográfica “Vínculos 2024” en honor a los animales.","en":"Awareness and Outreach: Initiatives such as the \"Capacita tu barrio\" project are led to promote responsible pet ownership. Additionally, the \"Animal Care\" programme was launched on UTV Channel, an expert advice space broadcast weekly, and the “Vínculos 2024” photographic exhibition was inaugurated in honour of animals."}}]},{"titulo":{"es":"Sostenibilidad, Innovación y Acción Climática","en":"Sustainability, Innovation and Climate Action"},"piezas":[{"t":"parrafo","zona":"cuerpo","texto":{"es":"La UDES aplica el conocimiento científico y la innovación para crear soluciones sostenibles que reduzcan el impacto negativo en el medio ambiente:","en":"UDES applies scientific knowledge and innovation to create sustainable solutions that reduce negative environmental impact:"}},{"t":"item","zona":"cuerpo","texto":{"es":"Innovación en Energías Limpias: La UDES presenta sus revolucionarios desarrollos en hidrógeno verde en la COP16, demostrando el potencial de la academia para transformar industrias y reducir emisiones.","en":"Innovation in Clean Energies: UDES presents its revolutionary developments in green hydrogen at COP16, demonstrating academia's potential to transform industries and reduce emissions."}},{"t":"item","zona":"cuerpo","texto":{"es":"Investigación Aplicada: Se impulsa la investigación en \"salud planetaria\" (Convocatoria SCOPUS/WOS) y se desarrollan soluciones como el innovador desinfectante respetuoso con el medio ambiente para la industria avícola, evaluado por el programa de Microbiología Industrial.","en":"Applied Research: Research in \"planetary health\" (SCOPUS/WOS call) is promoted and solutions such as an innovative environmentally friendly disinfectant for the poultry industry are developed, evaluated by the Industrial Microbiology program."}},{"t":"item","zona":"cuerpo","texto":{"es":"Acción Comunitaria Sostenible: A través de la alianza con Veolia, se graduaron 52 líderes en el proyecto \"Comunidades Sostenibles\". Paralelamente, el proyecto \"El Recolector\" (del programa de Instrumentación Quirúrgica) implementa huertas caseras en Hogares Crea, cultivando cambio social y ambiental.","en":"Sustainable Community Action: Through the alliance with Veolia, 52 leaders graduated in the \"Sustainable Communities\" project. Meanwhile, the \"El Recolector\" project (from the Surgical Instrumentation program) implements home gardens in Hogares Crea, cultivating social and environmental change."}},{"t":"item","zona":"cuerpo","texto":{"es":"Cultura de Reducción: La UDES lidera jornadas de recolección de residuos pos consumo (logrando 300 kg) y fomenta la movilidad sostenible, logrando una reducción de 4.758 kg de CO₂ en el \"día sin carro\".","en":"Culture of Reduction: UDES leads post-consumption waste collection days (achieving 300 kg) and promotes sustainable mobility, achieving a reduction of 4,758 kg of CO₂ on the \"car-free day\"."}}]}],"bloques":[{"sec":"tesis","text":"La Universidad de Santander (UDES) reafirma su compromiso misional con el entorno, asumiendo un rol de liderazgo en la implementación de los Objetivos de Desarrollo Sostenible (ODS) en la región. Como una de las instituciones líderes en sostenibilidad ambiental en el país, la UDES integra la protección del planeta en su quehacer diario.","text_en":"The University of Santander (UDES) reaffirms its mission-driven commitment to the environment, taking a leadership role in implementing the Sustainable Development Goals (SDGs) in the region. As one of the country's leading institutions in environmental sustainability, UDES integrates planet protection into its daily work.","pos":1,"enabled":true,"warn":null},{"sec":"cifras","text":"En línea con nuestra política de transparencia y gestión basada en resultados, destacamos las siguientes cifras clave que resumen nuestro impacto directo en la promoción del ODS 15:","text_en":"In line with our policy of transparency and results-based management, we highlight the following key figures that summarise our direct impact in promoting SDG 15:","figs":[{"v":"4.758 kg","label":"Reducidos durante la jornada del \"día sin carro y sin moto\" en Bucaramanga, gracias a la participación activa de nuestra comunidad universitaria.","src":"Informe 2025","v_en":"4,758 kg","label_en":"Reduced during the \"car and motorcycle free day\" in Bucaramanga, thanks to the active participation of our university community."},{"v":"300 kg","label":"Recolectados en la 19ª jornada de recolección de residuos pos consumo en Bucaramanga, liderada por la UDES para promover la sostenibilidad.","src":"Informe 2025","v_en":"300 kg","label_en":"Collected during the 19th post-consumption waste collection day in Bucaramanga, led by UDES to promote sustainability."},{"v":"52","label":"Líderes comunales de Girón formados como promotores del cuidado del medio ambiente gracias a la alianza \"Comunidades Sostenibles\" entre la UDES y Veolia.","src":"Informe 2025","v_en":"52","label_en":"Community leaders from Girón trained as promoters of environmental care thanks to the \"Sustainable Communities\" alliance between UDES and Veolia."},{"v":"19 años","label":"De investigación del Laboratorio de Tejidos Vegetales UDES, protegiendo la biodiversidad agrícola y luchando contra la extinción de especies nativas de Santander mediante biotecnología.","src":"Informe 2025","v_en":"19 años","label_en":"Years of research by the UDES Plant Tissue Laboratory, protecting agricultural biodiversity and combating the extinction of native Santander species through biotechnology."},{"v":"16","label":"Nuevos pasantes del programa de Medicina Veterinaria entregados al país, fortaleciendo el capital humano dedicado al bienestar animal.","src":"Informe 2025","v_en":"16","label_en":"New interns from the Veterinary Medicine program delivered to the country, strengthening human capital dedicated to animal welfare."}],"pos":2,"enabled":true,"warn":null},{"sec":"hicimos","text":"Protección de la Biodiversidad y Ecosistemas Estratégicos. La UDES enfoca sus esfuerzos en la conservación activa de la riqueza natural de la región: Defensa de Ecosistemas Clave: La UDES reafirmó su compromiso con el medio ambiente participando activamente en la Cumbre de Páramos 2024 en Bucaramanga, un espacio vital para la protección de estos ecosistemas estratégicos. Conservación de Flora Nativa: Ante la amenaza de extinción de especies como las orquídeas santandereanas, el Laboratorio de Tejidos Vegetales UDES (con 19 años de trayectoria) utiliza la biotecnología para propagar in vitro especies de interés y proteger la biodiversidad. Acción por el Agua: En alianza con la UPC, se desarrolla un diagnóstico sobre la calidad del agua en el Caño El Pital (Aguachica), fundamental para la salud del ecosistema local. Restauración y Siembra: La universidad participó activamente en la jornada de siembra en conmemoración del Día del Árbol en el Batallón de Servicios #5 Mercedes Ábrego.","text_en":"Protection of Biodiversity and Strategic Ecosystems. UDES focuses its efforts on the active conservation of the region's natural wealth: Defense of Key Ecosystems: UDES reaffirmed its commitment to the environment by actively participating in the 2024 Páramos Summit in Bucaramanga, a vital space for protecting these strategic ecosystems. Conservation of Native Flora: Facing the threat of extinction of species such as Santander orchids, the UDES Plant Tissue Laboratory (with 19 years of experience) uses biotechnology to propagate in vitro species of interest and protect biodiversity. Action for Water: In partnership with UPC, a diagnosis of water quality is being developed in Caño El Pital (Aguachica), fundamental for the health of the local ecosystem. Restoration and Planting: The university actively participated in the planting day commemorating Tree Day at Battalion of Services #5 Mercedes Ábrego.","encabezado":"Protección de la Biodiversidad y Ecosistemas Estratégicos","pos":3,"enabled":true,"warn":null},{"sec":"hicimos","text":"Bienestar Animal como pilar del Ecosistema. Reconociendo que la fauna es parte integral de los ecosistemas, la UDES ha consolidado una robusta estrategia de bienestar animal a través de la academia y la extensión: Alianzas Estratégicas: La Clínica Veterinaria UDES ha fortalecido su servicio a la comunidad mediante alianzas clave con Kahu, para ampliar los servicios al sector externo, y con Cajasan, consolidando una colaboración de más de un año para ofrecer descuentos y asistencia. Formación de Alta Calidad: Se entregaron 16 nuevos pasantes de Medicina Veterinaria en la conmemoración de su día. Además, se promueve la excelencia académica con movilidades internacionales de estudiantes a instituciones de prestigio como la Universidad de Pisa en Italia. Sensibilización y Extensión: Se lideran iniciativas como el proyecto \"Capacita tu barrio\" para promover la tenencia responsable de mascotas. Adicionalmente, se lanzó el programa \"Cuidado Animal\" en el Canal UTV, un espacio de asesoría experta emitido semanalmente, y se inauguró la exposición fotográfica “Vínculos 2024” en honor a los animales.","text_en":"Animal Welfare as an Ecosystem Pillar. Recognising that fauna is an integral part of ecosystems, UDES has consolidated a robust animal welfare strategy through academia and outreach: Strategic Alliances: The UDES Veterinary Clinic has strengthened its community service through key alliances with Kahu, to expand services to the external sector, and with Cajasan, consolidating a collaboration of over a year to offer discounts and assistance. High-quality Training: 16 new Veterinary Medicine interns were delivered on their day of commemoration. In addition, academic excellence is promoted with international student mobilities to prestigious institutions such as the University of Pisa in Italy. Awareness and Outreach: Initiatives such as the \"Capacita tu barrio\" project are led to promote responsible pet ownership. Additionally, the \"Animal Care\" programme was launched on UTV Channel, an expert advice space broadcast weekly, and the “Vínculos 2024” photographic exhibition was inaugurated in honour of animals.","encabezado":"Bienestar Animal como pilar del Ecosistema","pos":4,"enabled":true,"warn":null},{"sec":"hicimos","text":"Sostenibilidad, Innovación y Acción Climática. La UDES aplica el conocimiento científico y la innovación para crear soluciones sostenibles que reduzcan el impacto negativo en el medio ambiente: Innovación en Energías Limpias: La UDES presenta sus revolucionarios desarrollos en hidrógeno verde en la COP16, demostrando el potencial de la academia para transformar industrias y reducir emisiones. Investigación Aplicada: Se impulsa la investigación en \"salud planetaria\" (Convocatoria SCOPUS/WOS) y se desarrollan soluciones como el innovador desinfectante respetuoso con el medio ambiente para la industria avícola, evaluado por el programa de Microbiología Industrial. Acción Comunitaria Sostenible: A través de la alianza con Veolia, se graduaron 52 líderes en el proyecto \"Comunidades Sostenibles\". Paralelamente, el proyecto \"El Recolector\" (del programa de Instrumentación Quirúrgica) implementa huertas caseras en Hogares Crea, cultivando cambio social y ambiental. Cultura de Reducción: La UDES lidera jornadas de recolección de residuos pos consumo (logrando 300 kg) y fomenta la movilidad sostenible, logrando una reducción de 4.758 kg de CO₂ en el \"día sin carro\".","text_en":"Sustainability, Innovation and Climate Action. UDES applies scientific knowledge and innovation to create sustainable solutions that reduce negative environmental impact: Innovation in Clean Energies: UDES presents its revolutionary developments in green hydrogen at COP16, demonstrating academia's potential to transform industries and reduce emissions. Applied Research: Research in \"planetary health\" (SCOPUS/WOS call) is promoted and solutions such as an innovative environmentally friendly disinfectant for the poultry industry are developed, evaluated by the Industrial Microbiology program. Sustainable Community Action: Through the alliance with Veolia, 52 leaders graduated in the \"Sustainable Communities\" project. Meanwhile, the \"El Recolector\" project (from the Surgical Instrumentation program) implements home gardens in Hogares Crea, cultivating social and environmental change. Culture of Reduction: UDES leads post-consumption waste collection days (achieving 300 kg) and promotes sustainable mobility, achieving a reduction of 4,758 kg of CO₂ on the \"car-free day\".","encabezado":"Sostenibilidad, Innovación y Acción Climática","pos":5,"enabled":true,"warn":null}],"conteo":{"tesis":1,"cifras":1,"hicimos":3,"proyectos":0,"viene":0,"cifras_figs":5,"videos":0,"enlaces":0,"copiados":0,"deshabilitados":0},"rarezas":["Sin «próximos pasos» en el HTML: el informe no tiene sección «viene»."]}$ods_json$::jsonb,
$ods_html$<!DOCTYPE html>
<html lang="es">
<head>
  <meta charset="UTF-8" />
  <meta name="viewport" content="width=device-width, initial-scale=1.0" />
  <title>ODS 15 · Vida de ecosistemas terrestres | Informe</title>
  <meta name="description" content="Plantilla base para informes ODS 15. Encabezado y secciones en blanco para completar." />
  <link href="https://fonts.googleapis.com/css2?family=Inter:wght@400;600;700&display=swap" rel="stylesheet">
  <style>
    :root { --sdg-accent: #56C02B; --sdg-accent-light: rgba(86,192,43,0.12); --text-primary: #2c3e50; --text-secondary: #546e7a; --bg-white: #ffffff; --border-light: #e8eaed; --shadow-sm: 0 1px 3px rgba(0,0,0,0.04);} * { box-sizing: border-box; margin: 0; padding: 0; } body { font-family: 'Inter', system-ui, -apple-system, Segoe UI, Roboto, Arial, sans-serif; color: var(--text-primary); background: var(--bg-white); } .container { max-width: 1160px; margin: 0 auto; padding: 0 28px; } .lang-switch { position: fixed; top: 16px; right: 16px; z-index: 110; display:flex; gap:8px; background:#f6f7f8; padding:4px; border-radius:10px; } .lang-switch button { border:0; background:transparent; padding:8px 14px; border-radius:7px; font-weight:600; color:var(--text-secondary); cursor:pointer; } .lang-switch button.active { background:#fff; color:var(--sdg-accent); box-shadow: var(--shadow-sm); } .hero { padding: 88px 0 72px; background: radial-gradient(circle at 50% 0%, var(--sdg-accent-light) 0%, #ffffff 65%); border-bottom:1px solid var(--border-light); clip-path: polygon(0 0, 100% 0, 100% 92%, 50% 100%, 0 92%); } .grid-2 { display:grid; grid-template-columns: 1.2fr 0.8fr; gap:32px; align-items:center; } .eyebrow { color: var(--sdg-accent); text-transform: uppercase; font-weight: 700; letter-spacing: .12em; font-size:12px; margin-bottom: 12px; display:inline-block; } h1 { font-size: clamp(32px, 5vw, 52px); line-height: 1.15; margin: 0 0 8px 0; } .hero-illustration { width:100%; height:auto; max-width:360px; margin:0 auto; display:block; border-radius:16px; } section { padding: 64px 0; } .section-title { font-size: clamp(24px, 3.5vw, 34px); margin-bottom: 8px; font-weight: 700; } .section-rule { height: 1px; background: var(--border-light); margin: 16px 0 24px; } footer { border-top:1px solid var(--border-light); padding: 28px 0; color:#6b7b86; }

    /* Barra de navegación ODS (v2) */
    .sdg-navbar { position: fixed; top: 0; left: 0; width: 100%; height: 8px; display: flex; z-index: 1000; background: transparent; }
    .sdg-nav-item { flex: 1; height: 8px; cursor: pointer; position: relative; transition: all 0.4s cubic-bezier(0.4, 0, 0.2, 1); text-decoration: none; display: flex; align-items: center; justify-content: center; overflow: hidden; }
    .sdg-nav-item::before { content: "ODS " attr(data-sdg); position: absolute; top: 50%; left: 50%; transform: translate(-50%, -50%); color: #fff; font-size: 10px; font-weight: 700; letter-spacing: 0.5px; z-index: 2; opacity: 1; transition: opacity 0.3s ease; pointer-events: none; text-shadow: 0 1px 2px rgba(0,0,0,0.2); }
    .sdg-nav-item:hover::before { opacity: 0; }
    .sdg-nav-item:hover { height: 320px; box-shadow: 0 4px 20px rgba(0,0,0,0.15); }
    .sdg-card { width: 100%; height: 100%; background: #fff; display: flex; flex-direction: column; opacity: 0; transition: opacity 0.3s ease 0.15s; }
    .sdg-nav-item:hover .sdg-card { opacity: 1; }
    .sdg-card-image { width: 100%; height: 220px; object-fit: contain; display: block; background: #fff; padding: 8px; }
    .sdg-card-content { padding: 16px; text-align: center; flex: 1; display: flex; flex-direction: column; justify-content: center; align-items: center; gap: 4px; }
    .sdg-card-number { font-size: 12px; font-weight: 700; text-transform: uppercase; letter-spacing: 1px; opacity: 0.9; }
    .sdg-card-title { font-size: 14px; font-weight: 600; color: #1a1a1a; margin: 0; line-height: 1.3; }
    /* Bilingüe para la barra */
    html[lang="es"] .lang-en { display: none !important; }
    html[lang="en"] .lang-es { display: none !important; }
    /* Paleta ODS */
    .sdg-1{background:#E5243B}.sdg-2{background:#DDA63A}.sdg-3{background:#4C9F38}.sdg-4{background:#C5192D}.sdg-5{background:#FF3A21}.sdg-6{background:#26BDE2}.sdg-7{background:#FCC30B}.sdg-8{background:#A21942}.sdg-9{background:#FD6925}.sdg-10{background:#DD1367}.sdg-11{background:#FD9D24}.sdg-12{background:#BF8B2E}.sdg-13{background:#3F7E44}.sdg-14{background:#0A97D9}.sdg-15{background:#56C02B}.sdg-16{background:#00689D}.sdg-17{background:#19486A}
    /* Utilidad bilingüe genérica */
    [data-lang-content]{display:none} [data-lang-content][data-visible="true"]{display:block}
    @media (max-width:768px){.sdg-nav-item:hover{height:280px}.sdg-card-image{height:180px;padding:6px}.sdg-card-content{padding:12px}.sdg-card-number{font-size:11px}.sdg-card-title{font-size:12px}}
    /* Grid and cards for cifras */
    .grid-4 { display:grid; grid-template-columns: repeat(4, 1fr); gap:24px; }
    @media (max-width:1024px){ .grid-4 { grid-template-columns: repeat(3,1fr); } }
    @media (max-width:768px){ .grid-4 { grid-template-columns: 1fr; } }
    .card { background:#fff; border:1px solid var(--border-light); border-radius:12px; padding:18px; text-align:center; box-shadow: var(--shadow-sm); }
    .uds-icon { font-size:28px; margin-bottom:8px; }
    .uds-number { font-size:34px; font-weight:800; color:var(--sdg-accent); margin-bottom:8px; }
    .uds-counter { font-variant-numeric: tabular-nums; }
    .card small { display:block; font-size:12px; color:var(--text-secondary); }
    /* Justify long text blocks */
    section p, section li, .container p { text-align: justify; text-justify: inter-word; }
  </style>
</head>
