        <div class="sdg-card">
          <img src="https://sdgbook.com/wp-content/uploads/sites/2/2019/09/2.png" 
               alt="ODS 2" 
               class="sdg-card-image"
               onerror="this.src='https://placehold.co/240x180/DDA63A/ffffff?text=ODS+2'">
          <div class="sdg-card-content">
            <div class="sdg-card-number" style="color: #DDA63A;">
              <span class="lang-es">ODS 2</span>
              <span class="lang-en">SDG 2</span>
            </div>
            <h3 class="sdg-card-title">
              <span class="lang-es">Hambre Cero</span>
              <span class="lang-en">Zero Hunger</span>
            </h3>
          </div>
        </div>
