    <!-- ODS 3 -->
    <a href="ods3_informe.html" class="sdg-nav-item sdg-3" data-sdg="3">
      <div class="sdg-card">
        <img src="https://sdgbook.com/wp-content/uploads/sites/2/2019/09/3.png" 
             alt="ODS 3" 
             class="sdg-card-image"
             onerror="this.src='https://placehold.co/240x180/4C9F38/ffffff?text=ODS+3'">
        <div class="sdg-card-content">
          <div class="sdg-card-number" style="color: #4C9F38;">
            <span class="lang-es">ODS 3</span>
            <span class="lang-en">SDG 3</span>
          </div>
          <h3 class="sdg-card-title">
            <span class="lang-es">Salud y Bienestar</span>
            <span class="lang-en">Good Health</span>
          </h3>
        </div>
      </div>
    </a>      <!-- ODS 4 -->
      <a href="ods4_informe.html" class="sdg-nav-item sdg-4" data-sdg="4">
        <div class="sdg-card">
          <img src="https://sdgbook.com/wp-content/uploads/sites/2/2019/09/4.png" 
               alt="ODS 4" 
